(window.STORIES=window.STORIES||[]).push(...[{"n": 51, "l": "الجزء التاسع عشر | حكمة الله في ابتلاء المؤمنين | والجزء العشرين.... | الهجره الأولي للحبشه | إسلام حمزه بن عبد المطلب", "u": "", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_التاسعة_عشرة\n#حكمة_الله_في_ابتلاء_المؤمنين\nوقفنا المرة إللي فاتت عند سؤالين مهمين الأول كان:\n¤ليه ربنا يبتلي المؤمنين وعلى رأسهم رسوله وأحب الخلق إليه كده ويسلط عليهم الكفار ؟\nربنا له حكمة في كل حاجة بيعملها فهو من أسمائه الحكيم،\nفاحنا مهما حاولنا نستنج الحكمة مش هنقدر نفهم ولا نُحيط  بالحكمة الكاملة، لكن بنحاول نفهم بعض الحكم دي\nفي البداية لازم نفهم قاعدة مهمة جدا\nرسول الله ﷺ هو القدوة إللي يجب علينا كمسلمين على مر العصور إننا نتبعها،\nطيب هنتبعه إزاي في موقف حصل لنا في حياتنا ولم يحصل لرسول الله ﷺ\nعشان كده كان لازم رسول الله ﷺ يمر بمختلف المواقف عشان نعمل نفس إللي هو عمله،\nفهنلاقي حياة رسول الله ﷺ جمعت كل الابتلاءات إللي ممكن تحصل لأي إنسان،\nعشان كده السيرة مش مجرد حكاية نسلي بها وقتنا،\nالسيرة منهج حياة لازم نعرفه ونفهمه ونطلع منه الحكمة والعبرة عشان نقدر نطبقه في حياتنا\n\" لَقَدْ كَانَ لَكُمْ فِي رَسُول اللَّه أُسْوَة حَسَنَة لِمَنْ كَانَ يَرْجُو اللَّهَ وَالْيَوْمَ الْآخِر\"\nودي مش حاجة اختيارية\nلأ..ده واجب على كل مسلم إنه يعرف حياة رسوله عشان يفهم القرآن ويفهم الواقع بتاعه لأن كل الأحداث بتتكرر بالحرف\nممكن واحد من المسلمين يموت له ابن، فيشوف رسول الله ﷺ اتصرف إزاي ويتصرف زيه\nممكن واحد تاني ابتلاؤه إن بناته تطلق، هيلاقي إن رسول الله ﷺ بناته اطلقت فيكون رد فعله زي رد فعل رسول الله ﷺ،\nممكن واحد ثالث يكون ابتلاؤه في أذى الناس له سواء بالشتم أو محاولات القتل، \nأو التشهير به أو مقاطعته أو الاعتداء عليه، وكل ده حصل مع رسول الله ﷺ وكان له تصرف مع كل موقف حسب وقته\nيعني في وقت لما تعرض للإيذاء سكت، \nومرة ثانية رد ودعا على المشركين ومرة ثالثة هيطلب من شاعره بعدين إنه يرد على المشركين بنفس أسلوبهم،\nفلازم نعرف امتى نتصرف في المواقف المختلفة في حياتنا  زي رسول الله ﷺ\n◇يبقى أول سبب من حكمة ربنا في تعرض رسول الله ﷺ للأذى والابتلاءات المختلفة هو إنه قدوة والناس يجب عليها إنها تقلده\n◇السبب الثاني هو:\n رفع درجاته في الجنة فيبتلى المرء على قدر دينه، وأكثر ناس دينهم كامل وإيمانهم قوى هم الأنبياء والرسل ،وأفضلهم أولي العزم وأفضل أولي العزم محمد ﷺ \n◇السبب الثالث هو : \nإن الناس تطمئن إن الابتلاءات حصلت لأكرم الخلق على الله وأحبهم إليه، \nيعني لما يحصل لواحد فينا ابتلاء هيطمن إن الابتلاء ده خير له وإنه مش بسبب إن ربنا غضبان عليه وإن الابتلاء علامة حب، \nلأن ربنا ابتلى قبله سيد الخلق أجمعين ، فتهدأ وتطمئن نفس المؤمن\nده كان بالنسبة لرسول الله ﷺ أما بالنسبة للمسلمين فالوضع هيختلف،\nربنا ابتلاهم بأذى الكفار لأسباب ثانية،\n◇ أولا:\nتنقية الصف المسلم، \nوخصوصا إن في ناس عبيد لهواها تقول أيوة احنا عبيد لله وبنطيع أوامره ولما ييجي الأمر بعكس هواها تلاقيها رجعت وسابت الدين،\nمفيش أسهل من أي واحد يقول أنا صدقت وآمنت بالله وبرسوله\nطيب إزاي الإنسان ده يبان صدقه من كذبه؟\nإذا حصل البلاء والأذى من الكفار\nهو إيه إللي يخلي واحد زي بلال ولّا خبّاب يصبر على التعذيب والظلم والقهر ده كله\nمش صدق الإيمان بالله؟\nلو هو واحد منافق يُظهر الإيمان ومن جواه مخبي الكفر إيه إللي يخليه يستحمل العذاب،\nهتلاقيه مع أول ابتلاء وأذى خلع\nوربنا قالها للمسلمين الأوائل:\n\"أَحَسِبَ النَّاسُ أَنْ يُتْرَكُوا أَنْ يَقُولُوا آَمَنَّا وَهُمْ لَا يُفْتَنُونَ ۩ \n وَلَقَدْ فَتَنَّا الَّذِينَ مِنْ قَبْلِهِمْ فَلَيَعْلَمَنَّ اللَّهُ الَّذِينَ صَدَقُوا وَلَيَعْلَمَنَّ الكاذِبين\"\nهتُفتن وتبتلى عشان تشوف نفسك إذا كنت صادق ولا كاذب\nعارفين زي إيه ولله المثل الأعلى \nلما يكون لك أصحاب وأهل متجمعين حواليك وكل واحد بيقول لك كلام جميل وإنه في ظهرك وهيقف جنبك مهما حصل،\nوأول ما تحصل لك مشكلة الكل يتخلى عنك ويبان إنهم كانوا كذابين مُدعين،\nده غير بقى إللي بيقعدوا يشمتوا فيك\nوكما قيل:\nجَزى اللهُ الشدائد عني كل خير...عرّفتني عدوِّي من صديقي\nتخيل بقى في وسط إللي انت فيه ده ولقيت شخص واحد منهم هو إللي واقف جنبك وبيواسيك ويساعدك، مشاعرك وإحساسك هيبقى عامل إزاي\nوهل مكانة الشخص ده في قلبك هتبقى زي مكانة الناس إللي تخلوا عنك؟\nطبعا لأ\nوهو ده بالضبط حال المؤمن الثابت رغم الابتلاءات وحال المنافق إللي بيبان مع أول اختبار بسيط،\nفكان لازم التمحيص ده عشان إللي هيتبقى وهيثبت هو إللي هيقوم على أكتافه نشر الإسلام \nوده يودينا للسبب الثاني وهو التربية\nربنا يريد لأمة الإسلام إنها تقود العالمين، وعشان تقودهم لازم يكونوا على طِراز مختلف من البشر، مفيش حاجة توقفهم ولا يخافوا من أي شيء،\nوخصوصا إن التمكين درجة الأنبياء ولا يكون التمكين إلا بعد المحنة\nفاللي يصبر ربنا هيُمكّن له \nوالابتلاء برنامج تدريبي يرفع مستوى الإيمان في القلب يوم عن يوم،\nزي الذهب كده لما الناس بتستخرجه من الأرض مش بيعرّضوه للنار ويمر بمراحل تنقية عشان يطلع الذهب اللامع إللي شكله حلو ده؟\nفالمسلم الصادق بيخرج من الابتلاء أقوى وأعظم\nالسبب الثالث هو تطهير النفس من الذنوب ورفع درجتها في الجنة،\nتخيلوا لما الشوكة تُكَفّر عن المؤمن خطاياه فما بالكم بالضرب والحبس والتعذيب والقتل؟\nالابتلاء بيطهر الانسان من الذنوب وطول ما في ذنوب لن ينتصر المسلمون ،\nوربنا هيسلط عليهم من يكفر الذنوب دي،\nفسنة كونية إن الإنسان لن يُمَكّن وربنا ينصره على أعدائه حتى يُبتلى\nده غير طبعا إن الابتلاء ده درس عملي من دروس التوحيد والإيمان والتوكل على الله\nلأن الإنسان بيعرف بطريقة عملية إنه ضعيف ملوش أي قوة إلا بالله، وملوش ناصر غيره سبحانه، \nفيتوكل على الله التوكل التام فيستحق لقب المؤمن إللي ربنا يُمكن له في الأرض\n¤أظن الكلام لحد هنا مقنع \nلكن السؤال المُحيّر بقى \nليه المسلمين ورسول الله ﷺ صبروا وتحملوا الألم ومردوش على الكفار وحملوا السلاح مثلا ودافعوا عن أنفسهم ولّا حتى قاموا عملوا ثورة على الظلم ده \nربنا قال لرسوله مع بداية الجهر بالدعوة إنه يعلن الدعوة ويعرض عن المشركين،\nيعني لا يرد عليهم بقتال ولا يصطدم معاهم حتى لو حصل أذى حتى لو حصل إهانة وذل حتى لو حصل قتل \n\"فَاصْدَعْ بِمَا تُؤْمَرُ وَأَعْرِضْ عَنِ الْمُشْرِكِينَ\"\nليه طيب كده\n♡أولا :\nربنا يريد إنه يعلّم المسلمين العرب الأوائل نوع جديد من الصبر،\nهم بطبيعتهم كانوا يقدروا يصبروا على الجوع والحر والفقر والحروب وطول السفر و...و...\nلكن الحاجة الوحيدة إللي مكنوش يقدروا عليها هي الصبر على تحمل الظلم\nطبيعة نفس العربي ثائرة مترضاش الظلم، معندوش أي مانع إنه يثور ضد ظالمه ويُقتل\nلكن دلوقتي الإسلام له أبعاد ثانية غير إن الواحد يبص لمصلحته الشخصية،\nاحنا محتاجين ناس تُقيم دولة فتخيلوا القِلة دي لو كل واحد ثار عشان يدفع الظلم عن نفسه وقُتل\nمش هيبقى في ناس تُقيم دولة الإسلام ولا تنشره،\nالموت في سبيل الله حاجة جميلة لكن لو كلنا متنا مين إللي هينشر الإسلام\nوفي كارثة تانية تخيلوا لو كل واحد ثار على إللي كان بيعذبه وممكن يقتله،\nكانت هيؤدي لسمعة سيئة جدا للإسلام، ليه؟\nلأن إللي كان بيعذب المسلمين هم أهلهم، كل واحد كان بيأخذ إللي أسلم من قبيلته ويعذبه\nزي عثمان بن عفان مثلا إللي كان بيعذبه عمه ، فلما كل واحد يثور ويقتل أهله الوضع هيكون إيه،\nوالكفار بيقولوا أصلا من غير حاجة إن الإسلام بيفرق بين الرجل وابنه والرجل وزوجته والرجل وعشيرته\nفربنا بيعلمهم وبيعلمنا برده تقديم مصلحة الأمة على مصلحتي الشخصية،\nمش أهم حاجة《 أنا 》أحقق مصلحتي وخلاص ومش مهم أي حد تاني ،\n الإسلام رباهم على إلغاء حتة ال《أنا》 دي،\nواحنا لو ملغينهاش هنفضل زي ماحنا \n♡ثانيا : ودي مهمة وخدوا بالكم منها\nتربية المسلمين على الطاعة المُطلقة والتامة لله ولرسوله،\nلأن الاختبار الحقيقي للطاعة هو أن يُطيع المسلم بدون جدل واعتراض حتى في المشاعر\nالمشاعر إللي بتثُور وتغلي بسبب الإحساس بالظلم والقهر ،\nوإللي الإنسان مش بيبقى قادر يتحكم فيها،\nربنا ربّى الصحابة إنهم حتى يتحكموا في مشاعرهم وتبقى مُقيدة بطاعة الله ورسوله\nفاكرين لما خبّاب بن الأرت راح لرسول الله ﷺ  وهو مشاعره كلها ألم واحساس بالظلم والقهر وطلب من رسول الله ﷺ إنه يدعو الله بتعجيل النصر،\nوهو كان شايف إن هي دي المصلحة دلوقتي ورسول الله ﷺ غضب وقال له إنكم قوم تستعجلون ،\nخبّاب سمع أطاع ومعترضش واتحكم بمشاعره وقيدها بطاعة الله ورسوله،\nوالمشاعر دي مهما حاولنا نتخليها مش هنقدر نحس بالألم إللي هو كان حاسس بيه ساعتها من شدة التعذيب والظلم والقهر\nومع ذلك حتى مقلش لرسول الله ﷺ طيب بس ادعي بس يا رسول الله وخلاص، أهه حاجة تهوّن بها عليّ إللي أنا فيه ده\nلأ...ده أخذ الكلام ورضي وصبر \nهنشوف إن شاء الله في صلح الحديبية لما عمر بن الخطاب غلبته مشاعره واعترض على أمر رسول الله ﷺ بسبب الظلم والقهر إللي كان شايفه بيحصل قصاده،\nومع ذلك رسول الله ﷺ قال له أنا عارف أنا بعمل إيه ولا أعصي الله،\nوأبو بكر الصديق قال له إلزم غرس رسول الله، يعني منين ما يحط رجله حط رجلك،\nفرضي عمر وهِدي وبعدين قال إنه قعد يعمل أعمال خير كثيرة عشان يكّفر اعتراضه على رسول الله ﷺ بسبب مشاعره إللي هي تعتبر طبيعية\nوهو ده الفرق بيننا وبينهم، هم عندهم الله ورسوله مقدمين حتى على مشاعرهم، \nوهنا يبان قول رسول الله ﷺ:\n\"لا يؤمن أحدكم حتى يكون الله ورسوله أحب إليه مما سواهما\"\nوالحب مش مجرد مشاعر الإنسان يحس بها ولا كلمات يقولها،\nالحب اتباع لمنهج الله ورسوله في كل شيء حتى في المشاعر \nقال رسول الله ﷺ:\n\"لا يؤمن أحدكم حتى يكون هواهُ تَبَعا لما جئتُ به\"\nعشان كده الصحابة سادوا الدنيا زي ما هنشوف وأخذوا مكانة أفضل مَن مشى على الأرض بعد الأنبياء،\nإللي عايز يبقى في مكانتهم ويوصل للنهاية إللي وصلوا لها لازم يمشي في نفس الطريق بتاعهم إللي مشيوا فيه،\n غير كده هيضيع \n\"وَأَنَّ هَذَا صِرَاطِي مُسْتَقِيمًا فَاتَّبِعُوهُ وَلا تَتَّبِعُوا السُّبُلَ فَتَفَرَّقَ بِكُمْ عَنْ سَبِيلِهِ ذَلِكُمْ وَصَّاكُمْ بِهِ لَعَلَّكُمْ تَتَّقُونَ \"\n♡ثالثا:\n في سنن كونية.. زي إللي بيقع في مياه عميقة وهو ميعرفش يعوم هيغرق، \nومن السنن الكونية إن الباطل له قوة فمينفعش للمسلمين إنهم يقولوا ربنا معانا واحنا على الحق ويدخلوا حرب خاسرة تقضي عليهم \nأيوة جند الله هم الغالبون، لكن الإسلام دين واقعي عملي،\nمش مبني على مشاعر البشر المتقلبة\nيشوف قوة العدو واحنا قوتنا أد إيه ونحط الخطط المناسبة عشان نقدر نحقق النصر\nيعني باختصار نأخذ بالأسباب مع التوكل على الله،\nفلو دلوقتي المسلمين قاموا وكلهم ثاروا وهم قِلة مستضعفة معندهمش أي امكانيات نهائي ..ممكن يقتلوا واحد ولا اثنين ولا حتى مائة من كفار مكة،\nلكن في المقابل هيتم إبادتهم جميعا، زي ما قلنا من شوية\nده غير إن القتال مكنش ضروري أوي لأن الغاية مكنتش حكم مكة، الغاية كانت نشر الإسلام في مكة،\nهي الدعوة أه ماشية بمشقة وبطلوع الروح ..بس ماشية\nبعكس لو اتفرضت فرض بالقوة على ناس أصلا العِزة والشرف والعُلو في دمهم،\nمحدش هيقبل بالدعوة ولا حتى هيسمعوا لها وهيعاندوا أكثر لو حصل صِدام بينهم وبين المسلمين،\nده همّ أصلا من أسباب معاندتهم اتباع دين الإسلام ضعف المسلمين\n☆وده يعلمنا إننا لما نيجي ندعي حد نشوف نفسية الشخص ده إيه،\nهل هو من النوع إللي بيتأثر أكثر بمظاهر الرحمة فيّ ،\nفأزود منها عشان أليّن قلبه، ولّا من النوع إللي بيتأثر لو شاف مني ذكاء ولا قوة،\nولّا من النوع إللي بيتأثر لو شاف مني لطف وأدب في الحوار وهكذا \n♡رابعا:\nمن حكمة ربنا في إعراض المسلمين عن المشركين وميكونش في صِدام،\nإن ربنا يعلم إن في ناس من كبار المشركين ومن أشدهم على المسلمين هيؤمنوا،\nوهيتأثروا بثبات المسلمين برغم كل الشدائد والصعوبات \nده غير إن تعرّض المسلمين للظلم هيكون سبب في تحرك بعض المشركين لنصرتهم زي ما هنشوف بعدين في قصة الحصار في شعب أبي طالب،\nوكمان سبب في إسلام واحد من أبطال المسلمين حمِية للظلم إللي وقع على رسول الله ﷺ\n \nاحنا دلوقتي لسه في السنة السادسة من البعثة،\nوالمشركين عمّالين يعذبوا في المسلمين ويعتدوا على رسول الله ﷺ،\nوأعداد المسلمين بتزيد وكانوا يخفون إسلامهم ،لكن كده هيبدأوا يظهروا والمشركين يعرفوهم\nففي نفس الوقت إللي احنا مش عايزينهم يظهروا فيه عشان ميتعذبوش،\nعايزين نخفف عن الناس إللي بتتعذب دي وفي نفس الوقت مش هينفع حرب أو إنهم يدافعوا عن نفسهم\nاحنا عايزين حل عملي ينفع مع المستضعفين دول وغيرهم من الناس إللي هتيجي في المستقبل\nهو ربنا كان ممكن ينقذ رسوله والمؤمنين بكلمة 《كن》\nلكن دي مش سنة التغيير ، رسول الله ﷺ بيعلمنا الأخذ بالأسباب إللي نقدر عليها،\nعشان محدش بعدين ييجي يقول أصل ده رسول الله ﷺ ومعاه المعجزات\nهنا مفيش معجزات ...كلها أسباب بشرية نقدر نعملها\nفالحل كان إنهم يشوفوا مكان تاني برة مكة يهاجروا له عشان يعبدوا الله فيها بدون تعذيب أو تهديد بالقتل\nيعني هيسيبوا أهلهم ووطنهم والأماكن إللي عاشوا فيها عمرهم وأموالهم وتجارتهم و....و... \nوده مش قرار سهل ، احنا دايما نسمع إن المسلمين هاجروا ونعدي الموضوع وأهه كلمة بتتقال\nلكن متخيلين واحد يسيب حياته المستقرة في بلده إالي بيحبها وكان عايش فيها مرتاح عشان بس قضية الدين\nيعني هم مش هيسيبوا البلد عشان يروحوا يشتغلوا ويحسنوا مستوى المعيشة بتاعهم مثلا،\nولّا هيروحوا بلد أعظم رفاهية فالموضوع كان هيبقى سهل عليهم،\nلأ، دول هيسافروا للمجهول، يا ترى هيلاقوا شغل ولّا لأ، ياترى البلد إللي هيروحوه ده حر ولا برد يا ترى...يا ترى... \n☆ودي حاجة جديدة الإسلام بيعلمها للصحابة وبيعلمها لنا،\nإن أرض الله واسعة، وإن أعظم قطعة في الأرض هي إللي نقدر نعبد ربنا فيها\nيعني احنا مش بنفضّل أرض على أرض بالأنهار والأشجار والعشيرة ،\nلكن هل نقدر نعبد فيها الله بدون أذى ولّا لأ، \nفهم هيسيبوا أشرف بقعة على الأرض وهي مكة ويروحوا مكان تاني بس عشان يعرفوا يعبدوا ربنا\nرسول الله ﷺ أمر بعض أصحابه بالهجرة للحبشة،\nوالحبشة بعيدة جدا عن مكة واللغة مختلفة تماما عن لغة العرب\nطيب ليه رسول الله ﷺ اختار الحبشة بالذات؟\nهو لخّص الموضوع كله في كلمتين:\nإن فيها ملك لا يُظلم عنده أحد \nمين هو الملك ده واشمعنى رسول الله ﷺ ذكر صفة العدل وإنه غير ظالم؟\nومين الشخصيتين إللي هيسلموا ويقلبوا الموازين لصالح المسلمين في مكة \nده إللي هنعرفه الجزء الجاي إن شاء الله\n☆#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_العشرون\n#الهجرة_الأولى_للحبشة\n#إسلام_حمزة_بن_عبد_المطلب\nاتكلمنا المرة إللي فاتت عن تزايد تعذيب الكفار للمسلمين عشان يرجعوا عن الإسلام،\nلكن رسول الله ﷺ فكر في فكرة عشان يحافظ بها على دعوة الإسلام من إن المشركين يقضوا عليها سواء بقتلهم للمسلمين أو تعذيبهم  لحد ما يرجعوا عن الدين،\nأو التكتيم الإعلامي إللي عملوه عشان محدش يعرف من خارج مكة أي حاجة عن الإسلام،\nلدرجة إن أي أحد ييجي من خارج مكة سمع عن رسول الله ﷺ وبيسأل مجرد سؤال،\nحب استطلاع يعني\n يضربوه\nفكان لازم يكون في حل أو فكرة ننقذ بها دعوة الإسلام،\nوالفكرة كانت إنه يسمح لبعض المسلمين للهجرة خارج مكة\nفالهدف الأساسي من الهجرة كان الحفاظ على دعوة الإسلام، مش الحفاظ على حياة الأفراد،\nومش معنى كده إن حياتهم مش مهمة..لأ طبعا مهمة لكن مقارنة بحفظ الدين ونشره فالدين هو رقم واحد\nوالدليل على كده إن رسول الله ﷺ مطلبش من المستضعفين إنهم يهاجروا زي بلال وخباب إللي كانوا بيتعذبوا\nلكن طلب من القرشيين إللي عندهم مَنعة في قومهم إنهم يهاجروا\nفلو كان السبب الرئيسي هو مجرد الحفاظ على الأرواح فقط كان الأولى هو خروج المستضعفين إللي معندهمش منعة في مكة\nده غير كده هجرة المسلمين من أشراف مكة بالذات لها أهداف تانية مهمة \nرسول الله ﷺ كان ذكي مكنش مجرد بشر ينزل له الوحي ويبلغ وخلاص،\nلأ..ده كان بيفكر وبيأخذ بالأسباب الدنيوية والوحي يؤيده\nفهو طلب من الأشراف الهجرة عشان \n◇أولا:\nلما الناس دي تهاجر ممكن أهل مكة يطاردوهم،\nفلو طاردوهم ومسكوهم مش هيقدروا يقتلوهم عشان هيخافوا من قبائلهم \nفأقصى حاجة هيعملوها إنهم هيرجعوا المهاجرين لمكة،\nلكن تخيلوا لو كان المهاجرين من العبيد كان إيه إللي كان ممكن يحصل لهم \nكانوا هيقتلوهم بدون أي تردد ماهم ملهمش حد يدافع عنهم\n◇ثانيا: \nالأشراف يقدروا يؤثروا في أهل البلد إللي هيهاجروا لها؛ \nلأن من طبيعة البشر إنهم يسمعوا للشخص ذو المكانة والشرف وعنده مركز،\nبعكس لو اتكلم شخص ضعيف محدش هينتبه له،\nزي مثلا لما المرأة بتتكلم مع زوجها في موضوع مهم وجاء ابنها الصغير عايز يشارك في الحوار ويقول رأيه،\nالمرأة هتسمع لرأي زوجها ولا رأي ابنها\nأكيد هتسمع كلام زوجها، مع إن سبحان الله ساعات ربنا بينطق الحق والرأي السديد على لسان الأطفال أو الضعفاء بصفة عامة\nفالغرض أصلا هو توصيل الدعوة للبلد إللي هيرحوه،\nفأكيد الوضع هيكون مختلف لما يكون الاشراف هم المهاجرين\n لأن البلد هتكون كأنها استضافت وفد سياسي محترم معارض لسياسة مكة،\nغير لما تستضيف من وجهة نظرهم مجموعة من العبيد الهاربين من اسيادهم\n◇ثالثا:\nلما الأشراف دول يهاجروا، ده هيعمل هزة اجتماعية في مجتمع مكة ويخلي الناس تتعاطف معاهم،\nيعني أحسن ناس هم إللي سابوا البلد وإللي كانوا بيسعوا لإصلاحها،\nويبدأوا يفكروا هم بيحصل فيهم كده ليه؟\nعشان بس عايزين يصلحوا ويعبدوا الله..إزاي نرضى نعمل في الناس دي كده\n \nعارفين زي إيه\nزي لما شاب يكون عليه مظاهر الصلاح والناس بتشهد له بالخير ويتسلط عليه ظالم يعذبه أو يقتله ،\nالناس هيكون رد فعلها إيه؟\nمش هتتعاطف معاه وتتأثر وتبدأ تفكر في الظلم وإزاي يتعمل في خيرة شبابها كده\nبعكس لو شاب بيشرب ولا شاب مُفسد في الأرض لو اتقتل حد هينتبه له أصلا \nففي المواقف دي يبدأ العقل يشتغل والعقل لما يشتغل بيشوف الحقيقة\nفرسول الله ﷺ كان بيشتغل على تحريك مشاعر أهل مكة من المشركين وعواطفهم لعل قلوبهم ترق ويبدأوا ياخدوا خطوات إيجابية \nلكن لو كان العبيد هم إللي خرجوا كان أهل مكة هيقولوا عادي يعني نجيب غيرهم\n☆لكن ممكن حد يسأل اشمعنى الحبشة بالذات \n رسول الله ﷺ اختار مدينة الحبشة بالذات مع إنها بعيدة عن أرض مكة،\nوهيبقى التواصل صعب جدا بين رسول الله ﷺ وبين المهاجرين من المسلمين،عشان حاكم الحبشة كان لا يْظلم عنده أحد\nزي ما هنشوف مثال على عدله بعدين إن شاء الله.\nفكرة الهجرة دي تحديدا كانت بعد حوالي سنتين ونصف من مرحلة الجهر بالدعوة\nيعني كانت في رجب من السنة الخامسة للبعثة،\nوكانت دي بداية الفرج للمسلمين مع إنه كان فرج بسيط ومكنش لكل المسلمين\nوفي أسباب تانية خلت رسول الله ﷺ يختار الحبشة بالذات عن غيرها من الأماكن،\nمنها : \n◇إنها بعيدة عن المشركين، يعني بين مكة وبين الحبشة بحر فمش هيقدروا يطاردوهم المسافة الطويلة دي\nوحتى لو حصل وطاردوهم فملك الحبشة ملك عادل مش هيسلم المسلمين لقريش؛\nبالرغم من إن في صحوبية تجمع بين أشراف مكة وبين ملك الحبشة\nبعكس الدول العربية...أقصد القبائل العربية\nلو المسلمين راحوا في أي قبيلة من القبائل دي مع إنها قريبة ونفس اللغة ونفس البيئة فمش هيبقى صعب إنهم يتكيفوا فيها لأنها مشابهة لأجواء مكة\nلكن المشكلة إن لو أهل مكة طلبوا من القبائل دي تسليم المسلمين هيسلموهم تسليم أهالي عادي جدا\nأمال يعني يخسروا علاقاتهم الاستراتيجية مع أهل مكة بسبب مجموعة من المفسدين في الأرض فارقوا دين الأباء والأجداد وقال إيه عايزين ينشروا الإصلاح في الأرض\nولو المسلمين راحوا اليمن مثلا فهي تحت حكم الفرس والفرس مجوس مشركين هم كمان فأكيد هيسلموا المسلمين لأهل مكة،\nده إذا الفرس نفسهم مقتلوش المسلمين أصلا\n◇وكمان الحبشة كان بلد تجاري واقتصادهم قوي،\nفمش هيحصل أزمة للبلد دي بسبب لجوء المهاجرين لها وبكده أهل البلد نفسهم مش هيعملوا مشاكل مع ملك الحبشة ويطلبوا منه إنه يطرد الناس دي\n◇ده غير إن الحبشة بلد مستقل يعني هي سيدة قرارها محدش بيعطيها معونات مثلا ولا حاجة ،فمفيش خطورة إن بلد تانية تجبرها على قرار هي مش عايزاه\nشوفتم رسول الله ﷺ كان بيدرس كل التفاصيل بدقة متناهية إزاي وبيخطط ويرتب ويدرس الأحوال السياسية والاقتصادية،\nأصل هو المسؤول عن أصحابه وهو القائد فلازم يبذل الأسباب إللي تؤمن حياة أتباعه\n☆معلومة عن إزاي الفرس حكمت اليمن \nفاكرين لما الأحباش كانوا حاكمين اليمن وبعدين أبرهة جاء عشان يهدم الكعبة وقُتل هو وجيشه،\nأبرهة كان سايب ابنه يحكم اليمن على ما يرجع،\nفكان في واحد من أهل اليمن الأصليين اسمه:\n《سيف بن ذي يزن》عايز يسترجع ملك اليمن من الأحباش، ملك آبائه وأجداده،\nفراح استعان بكسرى في قصة طويلة ملخصها إن كسرى أرسل مع سيف بن ذي يزن جيش من المساجين فحاربوا معاه وانتصروا على الأحباش،\nوبدل ما يرجعوا ملك اليمن لسيف بن ذي يزن حكموه هم وبقت اليمن تحت الحكم الفارسي \nوكان حاكم اليمن من الفرس في زمن رسول الله ﷺ اسمه 《باذان》خليكم فاكرين الاسم عشان هيكون له معانا قصة بعدين\nأخبر رسول الله ﷺ أصحابه بأمر الهجرة، فخرج للحبشة حوالي اثنا عشر رجل وامرأتين،\nمنهم عثمان بن عفان وزوجته رقية بنت رسول الله ﷺ،\nكان تزوجها بعد ما ابن أبو لهب طلقها \nفلما خرجوا عشان يركبوا البحر سادات مكة عرفوا وبعثوا وراهم ناس عشان ترجعهم،\nلكن لما وصلوا كان المسلمين خلاص أبحروا فمقدروش يوصلوا لهم وهاجروا بسلام\nطبعا استمر أذى المشركين وتعذيبهم للصحابة،\nيعني الحاجات إللي قلناها قبل كده من التعذيب كانت مستمرة مش بتقف ،\nحتى إهانة المشركين لرسول الله ﷺ مكنتش بتقف \n لحد ما جاءت السنة السادسة للبعثة،\nفي يوم من الأيام ورسول الله ﷺ عند جبل الصفا عدى عليه أبو جهل وهو لوحده فقعد يشتم في رسول الله ﷺ شتيمة جامدة\nورسول الله ﷺ لا يرد عليه، فاتغر أبو جهل بصبر وحلم رسول الله ﷺ فتجرأ وأخذ حَجر وقذف به رأس رسول الله ﷺ،\n فالحَجر فتح رأسه عليه الصلاة والسلام\nومشي أبو جهل وراح لأصحابه عند الكعبة يحكي لهم إللي حصل ويتفاخر بانتصاره على رسول الله ﷺ\nورجع رسول الله ﷺ إلى بيته...\n☆طبعا أنا مش هتكلم عن المشاعر إللي كان حاسس بها رسول الله ﷺ بعد الموقف ده\nلكن تخيلوا هو اتحمل أد إيه في سبيل الدعوة ..واحنا لمجرد حد يقول لنا كلمة ولا كلمتين نفسيتنا تتعب و نقول خلاص مش هندعي حد تاني \nكان شاف الموقف ده مَولاة من الموالي ، والمولاة هي الأمة المحررة ،\n☆شوفتم وما يعلم جنود ربك إلا هو \nوهي ماشية قابلت رجل هو من سادات مكة الأقوياء ومن قوته أنه كان بيخرج للصيد والقنص وكان بيصطاد الأسود\nفكان راجع لسه من الصيد وهو حاطط قوسه على ظهره ،\nومكنش يروح البيت لما يرجع من الصيد إلا لما يطوف بالكعبة،\nوكان يقابل الناس ويسلم عليهم ويكلمهم وهو بيطوف ،\nوكانت شخصيته قوية والناس بتهابه\nفالمرأة دي قالت له: \nلو شفت إللي حصل من شوية لابن أخوك محمد من أبي الحكم عمرو بن هشام \nكان هنا وشتمه وضربه...ومحمد سابه ومشي\nكان العم ده هو حمزة بن عبد المطلب، ومش بس عم ده كان أخوه من الرضاعة،\nفغضب حمزة جدا ومشي ناحية الكعبة في المكان إللي بيقعد فيه أبو جهل،\nوماشي مش بيكلم حد ووشه غضبان والناس شايفاه ..ياترى في إيه مش من عوايده كده\nفضل ماشي لحد ما وصل عند ابو جهل وهو وسط أصحابه وأبو جهل شايفه جاي من بعيد ومتوقع بقى إنه جاي يسلم عليه زي ما بيعمل \nفلسه هيتكلم راح حمزة ماسك القوس بتاعه ومديله على دماغه فاتحها له أكثر مما عمل مع رسول الله ﷺ\n☆أحسن يستاهل \nوحمزة لسه مش حاسس إنه انتقم لابن اخوه ولسه مشاعره مهديتش\n فحب إنه يكيد أبو جهل ويغيظه ويحرق دمه راح قايل له:\nإنت بتشتم محمد وأنا على دينه وبقول إللي بيقوله..رد علي كده لو تقدر \nأبو جهل كان قاعد وسط قبيلته وأصحابه وهو من قبيلة بني مخزوم القوية المسؤولة عن التخطيط للحروب،\nوحمزة من قبيلة بني هاشم القوية برده وليهم شرفهم بين الناس،\nفكده ممكن تقوم حرب\nفأصحاب أبو جهل قاموا عايزين ينتقموا من حمزة فقال لهم أبو جهل:\nسيبوا أبا عمارة فأنا الغلطان ...أنا فعلا شتمت ابن أخوه وأذيته جدا\nفسابه حمزة ورجع لبيته...وبعدين حصلت الصدمة \nأنا مش على دين محمد \nأنا إزاي قلت كده\nوقعد طول الليل يفكر مش عارف يعمل إيه\nهل يروح ويقول لهم إنه كذب وإنه مش على دين محمد وده عيب جدا عندهم،\nولّا يروح ويرجع في كلامه ويقول إنه ساب الدين ولّا يدخل في الدين وخلاص\nفدعا\nدعا الله بصدق : يارب لو دين محمد ده حق فاجعل تصديقه في قلبي، يعني خليني مؤمن،\nولو مش حق طلعني من الورطة دي\nفوقع تصديق الإسلام في قلب حمزة واطمان له وراح تاني يوم لرسول الله ﷺ يُعلن إسلامه\n☆طبعا مش هقول لكم على فرحة رسول الله ﷺ كانت عاملة إزاي \nإنتم حطوا نفسكم مكانه هتحسوا إن شاء الله بالسعادة إللي هو حس بيها \nوطبعا قريش قللت من أذاها لرسول الله ﷺ بسبب إسلام حمزة \nشوفتم إزاي إن الإنسان ممكن يكره شيء يحصل له لكن في النهاية هو خير\nرسول الله ﷺ مكنش عارف إن الموقف المؤلم إللي حصل له ده هيكون سبب في سعادة له مكنش متوقعها أبدا \nماهو بشر لا يعلم الغيب إلا لو ربنا قال له \nفكم في حياتنا من مواقف تضايقنا وتألمنا من بدايتها لكن العاقبة كانت خير\nفأبشروا \nرُبّ أَمرٍ تَتّقِيهِ.... جَرّ أَمرًا تَرتَجِيهِ\nخَفِيَ المحبوب منه... وبَدَا المَكرُوهُ فيهِ\nبعد إسلام حمزة بثلاثة أيام فقط حصلت حادثة قلبت كل موازين القُوى في مكة وهيكون لها الأثر على مدى التاريخ كله\nياترى إيه إللي حصل \nهنعرف الجزء الجاي إن شاء الله\n◇ملحوظة للأمانة العلمية:\nقصة إسلام حمزة رضي الله عنه ذكرها أهل السير، لكن سندها فيه ضعف، فلأن القصص والسِّير لا ينبني عليها أحكام شرعية فنذكرها من هذا الباب،\nوهذه فقط هي القصة الوحيدة التي وردت في إسلام حمزة رضي الله عنه، لهذا ننقلها من باب الاستئناس فقط."}, {"n": 52, "l": "الجزء الواحد وعشرين | إسلام عمر بن الخطاب | والجزء 22 | بين هجرة الحبشه الأولي والثانيه", "u": "", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية_إيمان_شلبي\n#الحلقة_الحادية_والعشرون\n#إسلام_عمر_بن_الخطاب\nكنا واقفين المرة إللي فاتت عند إسلام حمزة بن عبد المطلب عم رسول الله ﷺ وأخوه من الرضاعة،\nوكان إسلامه في السنة السادسة من البعثة،\nقبل ما نعرف إيه إللي حصل بعد إسلامه بثلاثة أيام تقريبا،\nهنرجع بالزمن شوية حوالي ثمانية أشهر كده تقريبا أو أكثر\nاحنا عارفين إن المشركين كانوا بيؤذوا المسلمين سواء المستضعفين أو السادة كل واحد على حسب مكانته،\nفكان من إللي قريش آذتهم أبو بكر الصديق صاحب رسول الله ﷺ،\nفهو كان من الناس إللي جَهرت بإسلامها بعد رسول الله ﷺ وكان الناس كلهم عارفين،\nكانت قريش بتؤذي أبو بكر سواء بالكلام أو حتى ساعات بالضرب،\nحتى يُروَى إنه في يوم من الأيام كان بيدعو الناس عند الكعبة، فقام الكفار وقعدوا يضربوه لحد ما وقع في الأرض مُغمى عليه،\nومش يسيبوه بقى \nده قعدوا يدوسوا عليه ومحدش قدر ينقذه منهم إلا عشيرته بنو تميم،\nوأخذوه وهو مُغمى عليه وكانوا متأكدين إنه خلاص بيموت لدرجة إن عشيرته هددوا كفار قريش إن لو مات أبو بكر مش هيسيبوهم\nفأخذوه ورجّعوه لبيته عند أمه\nتخيلوا لما أم ابنها يرجع لها بالمنظر ده إحساسها هيبقى إيه\nومع ذلك أبو بكر مسبش الدعوة إلى الله\nعارفين لو كان أبو بكر في عصرنا دلوقتي وعمل كده هيطلع لنا كائنات لزجة تقول \n:\nهو إللي غلطان إيه إللي وداه هناك \nاحنا لو مشينا بالمنطق ده لا حد هيأمر بمعروف ولا حد هينهى عن المنكر بسبب إن كل واحد خايف من الناس وخايف على حياته\nوده الفرق بيننا وبين الصحابة...الصحابة كانوا بيبذلوا أرواحهم في سبيل تبليغ الدعوة ونشر الإسلام مكنش بيهمهم أي حاجة \nلما اشتد الأذى على المسلمين ورسول الله ﷺ أمر الصحابة بالهجرة للحبشة خرج أبو بكر مهاجر للحبشة وبعد ما سافر مسافة يوم أو يومين قابل واحد اسمه 《ابن الدَّغِنّة》 من أشراف العرب،\nفقال لأبي بكر:\nإنت رايح فين \nفقال له أبو بكر: مهاجر للحبشة أعبد ربي .. لأن قومي أخرجني وآذوني \n☆مع إن أبو بكر في السنة دي اتولد له بنت صغيرة اسمها عائشة من زوجته أم رومان ومع ذلك برده خرج للهجرة، \nمع إن الإنسان بطبيعته هيكون قلقان على زوجته وبنته الصغيرة وهو خارج مش عارف هيرجع امتى \nالمهم ابن الدغنة قال له: ليه \nإنت إللي زيك ميخرجش\nإنت رجل بتُحسن لأقاربك بالمال أو الخدمة وغيرها،\nوإنت صادق في كلامك عمرك ما كنت بتكذب، وكنت بتساعد الضعيف واليتيم وصاحب العيال الفقير،\nوكمان كنت بتكرم ضيوفك وأي حاجة فيها خير مكنتش بتتأخر عنها\nفارجع لمكة وأنا سأجيرك من قريش ، يعني هتبقى تحت حمايتي\n☆فاكرييييين دي صفات مين \nنفس الصفات إللي خديجة زوجة رسول الله ﷺ قالتها له يوم ما رجع من الغار خايف\nشوفتم الشبه إللي بين أخلاق رسول الله ﷺ  وأخلاق أبي بكر \nرجع أبو بكر الصديق لمكة مع ابن الدغنة وراح عند الكعبة ووقف بين سادات قريش وقال لهم : \nأنا سأُجير أبا بكر\nإزاي تخرجوا رجل بيساعد المظلوم والفقير ويكرم الضيف و....و...\nفرجع أبو بكر لبيته وبدأ يصلي ويقرأ القرآن في حوش بيته،\nوكان أبو بكر مبيقدرش يمسك دموعه لما يقرأ القرآن ،\nمن أول ما يقرأ الفاتحة يبكي\nفكان يقرأ ويصلي ويبكي والنساء والأطفال يعدوا عليه، ولما يشوفوه كده كانوا يقفوا يشوفوا إيه ده...رجل يقرأ ويبكي \nوطبعا إن رجل يبكي ده كان حاجة غريبة بالنسبة لهم\nلأن رجال مكة معروفين بالشدة والغلظة والقوة ،\nفإزاي رجل يبكي كده\nطبعا سادات مكة مش عاجبها الوضع،\nالنساء والأطفال هيُفتنوا بأبي بكر كده ومش بعيد يدخلوا الإسلام\nراحوا لابن الدغنة قالوا له :\nشوف صاحبك\nيا إما تخليه يصلي داخل بيته يا إما يرد عليك جوارك لأننا مش هنسكت\nفراح ابن الدغنة لأبي بكر وقال له : \nإن سادات مكة اشتكوا...فإما تصلي داخل بيتك أو ترد على جِوَاري، \nلأني محبش إن الناس تسمع إن في حد نقض جِوَاري \n☆وكان موضوع الجوار أو الحماية ده عندهم عظيم جدا\nفقال له أبو بكر: لأ...أنا هرجع لك جوارك وحمايتك وهرضى بجوار الله، وطبعا الناس ما صدقوا وبدأوا يؤذوه تاني\n☆في ناس ممكن تستغرب هو ليه ابو بكر بيعمل كده،\nما يعبد ربنا وخلاص في بيته لازم مشاكل يعني\nشوفوا،\nالكفار مش هيرضوا ولا يهدأوا غير لما المسلمين يرجعوا عن دينهم،\nفلو جوّه ولا برة مش هيسيبوه...كده كده هيؤذوه\nفخلاص بقى مادام كده كده هم هيؤذوني يبقى أعمل إللي أنا عايزه\n من باب:\nإذا ضَربتَ فأوْجِع فإن العاقبة واحدة\nوفي نقطة كمان \nإن إللي قصادك بيشوفك لما يضغط عليك هتعمل إيه،\nهل هتضعف وتعمل إللي هو عايزه ولا هتقف وتقاوم\nلو الإنسان ضعف من البداية وتنازل ...خلاااص سلسلة التنازلات اتفتحت مش هيقدر يرجع \nلكن لو من أول خطوة كده ثبت على مبدأه وكمان يزود بحاجات تانية بالعند فيهم؛\nهم إللي هيتراجعوا أو على الأقل مش هيطلبوا تنازلات تانية\nيعني كأنه بيقول: مش عاجبك كذا خلاص خذوا ده وده وده\n فيبدأ التفاوض عالجديد ويسيب إللي كان عايزه مننا أصلا\nفهو ده إللي أبو بكر عمله، همّ كانوا بيؤذوه عشان يسيب الإسلام...طيب أنا مش هسيبه وهطلع أصلي برة البيت وهروح أدعو الناس عند الكعبة\nفاتحولت المفاوضات من إنه يسيب الإسلام لإنه يعبد ربه داخل بيته\n☆اتعلموا بقى من أبي بكر الصديق \nلما حد يضغط عليكم في حاجة غلط اثبتوا ومتضعفوش\n وبالعكس كمان زودوا إنتم من طلباتكم هتلاقوا الناس بدأت تتراجع عن الضغط ده\n \nوخير وسيلة للدفاع هي الهجوم\nوسط الناس إللي كانت بتؤذي المسلمين واحد اسمه عمر بن الخطاب وكان من سادات قريش على صِغر سنه \nوهو يبقى ابن أخت أبو جهل إللي حاول يقتل رسول الله ﷺ وكان بيؤذيه على طول ده\nعمر بن الخطاب اتعلم القراءة والكتابة ودي حاجة مكنش حد يعرفها كتير،\nيعني كان أعداد قليلة إللي كانوا بيعرفوا القراءة والكاتبة ومنهم عمر\nأبوه الخطّاب كان رجل ذكي معروف بشدته وغلظته وكان شجاع وجريء، \nتخيلوا ابنه عمر هيكون إزاي لما الأب كده\nوكان ربنا أعطى له جسم ضخم ،\nوكان بيلعب رياضة فأجاد المصارعة وركوب الخيل والفروسية، حاولوا تتخيلوا الشكل كده\nوكان عمر زيه زي الشباب في عصره بيحب اللهو وبيشرب الخمر وورث من أبيه ميله لكثرة الزوجات،\nفتزوج في حياته تسع نساء \nولما جاء الإسلام وبدأ سادات مكة يعذبون المسلمون كان عمر من أشد الناس تعذيبا للمسلمين\nلما رسول الله ﷺ أذن للمسلمين بالهجرة للحبشة كانوا بيخرجوا مُتَسَلّلِين،\nيعني مستخبيين عشان محدش يحس بهم \nفي يوم من الأيام لما كان واحد من الصحابة اسمه عامر بن ربيعة وزوجته ليلى بنت أبي حَثمة خارجين عشان يهاجروا،\nعامر بن ربيعة رجع يجيب حاجة وساب زوجته مستنياه على ما يرجع،\nفوهي مستنية زوجها إذ فجأة لقت إللي جاي ناحيتها\nلقيته عمر بن الخطاب\nهيعمل إيه...يا ترى هيأخذها ويعذبها ويهدد زوجها بيها\nولّا هيروح يجيب سادات قريش ويمعنوهم من الهجرة\nفشافها متجهزة للسفر فقال لها : \nإنتِ خلاص مسافرة يا أم عبد الله\nفقالت له: أيوة، والله لنخرج من البلد دي بسبب قهركم وآذيتكم لنا لحد ما ربنا يفرجها من عنده\nفقال لها:\nصَحِبَكمُ الله\n...وسابها ومشي\nوأم عبد الله واقفة مستغربة ومصطدومة \nأول مرة تشوف منه الرقة دي...هو ده عمر...يقول لي مع السلامة وكمان وهو حزين\nوهي واقفة كده جاء زوجها عامر بعد ما جاب الحاجات بتاعتهم،\nفقالت له: أما لو كنت شفت عمر من شوية ورقته معايا \nفقال لها: إنتي طمعتي إنه يُسلم\nقالت له : أه\nفقال لها: والله لا يُسلم إلا لو حمار الخطاب أسلم\nيعني لو الحمار أسلم ممكن عمر يسلم\nوقال كده بسبب إللي كان بيشوفه من شدة قسوة وغلظة عمر \nعمر دلوقتي في صراع نفسي:\nإيه الدين ده إللي يخلي الناس تتخلى عن كل شيء في حياتها مقابل إنها تحافظ عليه كده،\nوإيه الثبات إللي هم فيه ده رغم العذاب إللي بيتعذبوه بقالهم أكثر من سنتين\nهل هم فعلا على حق...قائدهم كنا بنقول عليه الصادق الأمين ،\nوبقالنا ست سنين في مناظرات ومفاوضات\nطيب لو أنا اتبعتهم هيكون موقفي إيه ...هل أدخل في الدين ده وأكون تابع لهم\nلكن أنا سيد من سادات مكة ومحدش يقدر يرد علي كلامي فكده مكانتي هتروح\nوكلام كثير يدور في رأس عمر\nوخصوصا إن حصل معاه موقف قبل بعثة رسول الله ﷺ\nفي يوم من الأيام بعد الجهر بدعوة الإسلام كان عمر بن الخطاب جالس وكان معاه ابنه عبد الله بن عمر، فعدى عليهم رجل جميل من المسلمين فقال عمر:\nأظن إن الرجل ده كان كاهن في الجاهلية\n◇الرجل ده قبل ما يُسلم كان شغال في الكهانة، يعني بيستعين بالجن عشان يقولوا له بعض أمور الغيب إللي كانوا بيسمعوها من الملائكة وهم بيتكلموا،\nوالكاهن غير الساحر،\nالساحر بيقول ويكتب طلاسم وكلام غير مفهوم.\nفيقول عبد الله بن عمر وهو بيحكي عن الموقف:\nوكان عمر لما يقول على حاجة: أظن كذا، إلا وكان ظنه في محله\nفقال عمر نادوا على الرجل ده،\nفلما جاء الرجل قال: أول مرة يُستقبل رجل مسلم الاستقبال ده\nيعني هو كان متعود على المعاملة السيئة من المشركين بسبب إسلامه، فالمرة دي عمر نفسه بيستقبله استقبال كويس.\nفقال له عمر إنه قال عليه إنه كان كاهن في الجاهلية \nفالرجل قال له فعلا أنا كنت كاهن \nفقال له عمر : إيه أعجب حاجة سمعتها من الجنية بتاعتك\nفقال له الرجل:\nفي يوم كنت في السوق فلقيتها جاية عليّ مفزوعة وقالت له:\nشوفت إللي حصل للجن بعد ماكانوا بيقعدوا عند أبواب السماء يسمعوا الغيب اتمنعوا منه، وأي حد بيحاول يسمع يترمى بالشهب\nوقعدوا يدوروا على السبب في منعهم من خبر السماء،\nلحد ما لقوا رجل بيقول لا إله إلا الله\nفقال عمر :صدق\nأنا برده لما كنت مرة عند البيت نائم عند الآلهة جاء رجل معاه عجل فذبحه،\nوفجأة سمعت حد بيصرخ بصوت مسمعتش زيه بيقول:\nيا جَلِيح《يعني يا وقح ويُقال إنه اسم لشخص》\n أمر نَجِيح 《يعني عرفنا إللي حصل》\nرجل فَصِيح 《رسول الله يعني》\nيقول : لا إله إلا الله ،\nفمعداش كم يوم إلا وقيل ظهر نبي\nيعني عمر رضي الله عنه سمع صوت جني بينادي على واحد اسمه جليح وبيقول له إن في نبي ظهر،\nفكده موقف الرجل المسلم إللي حكاه لعمر موافق للموقف إللي حصل لعمر نفسه\nفساعتها دخل الإسلام في قلب عمر بس لسه مأسلمش\n《القصة موجودة في صحيح البخاري》\nفي يوم من الأيام يُقال إنه بعد إسلام حمزة بن عبد المطلب بثلاثة أيام،\nكان عمر رايح عند الكعبة فلقى رسول الله ﷺ لسه جاي وهيصلي،\nفكبر رسول الله ﷺ وبدأ في الصلاة وبدأ يقرأ سورة الحاقة وعمر يسمع القرآن من رسول الله ﷺ:\n\"الْحَاقَّةُ. مَا الْحَاقَّةُ. وَمَا أَدْرَاكَ مَا الْحَاقَّةُ. \nكَذَّبَتْ ثَمُودُ وَعَادٌ بِالْقَارِعَةِ. فَأَمَّا ثَمُودُ فَأُهْلِكُوا بِالطَّاغِيَةِ.......\"\nفيقول عمر أنا بسمع وأتعجب من الكلام \nفقال عمر : ده والله شاعر\nفقرأ رسول الله ﷺ :\n\" إِنَّهُ لَقَوْلُ رَسُولٍ كَرِيمٍ ۩ وَمَا هُوَ بِقَوْلِ شَاعِرٍ قَلِيلًا مَا تُؤْمِنُونَ\"\nفقال عمر : يبقى كاهن\nفقرأ رسول الله :\n\" وَلَا بِقَوْلِ كَاهِنٍ قَلِيلًا مَا تَذَكَّرُونَ ۩ تَنْزِيلٌ مِنْ رَبِّ الْعَالَمِينَ\"\nقال عمر:\nفوقع الإسلام في قلبي..كل الشكوك راحت وتيقن إن هو ده دين الحق\nوبعدها راح لرسول الله ﷺ فأسلم،\nوأصابته دعوة رسول الله :\n\"اللهم أعز الإسلام بأحب هذين الرجلين إليك بأبي جهل أو بعمر بن الخطاب ، \nقال : \"وكان أحبهما إليه عمر \"\nوفرح به رسول الله ﷺ والمسلمين فرح شديد جدا \nوبعد ما أسلم عمر بن الخطاب راح وسأل بين الناس مين أكثر واحد بينقل الكلام في مكة \nفقيل له :\nجميل بن مَعمَر\nفراح له عمر وقال له: يا جميل معرفتش إللي حصل \nأنا أسلمت ودخلت في دين محمد \nفجميل بن معمر مكلموش ولا سأله ولا رد عليه\nراح واخد هدومه وطالع وعمر وراه لحد ما وصل لباب المسجد وصرخ بأعلى صوته:\nيا معشر قرااااايش لقد صبأ عمر \n☆الصابئ يعني إللي بيغير دينه،\nفقال له عمر:\nكذبت...بل أنا أسلمت\nفراح الناس قايمين عليه وقعدوا يضربوه\nوهو مسكتش\n \nقعد يضرب فيهم هو كمان \nوقعدوا يضربوا في بعض مدة طويلة لحد ما عمر وقع مبقاش قادر يقوم\nوراح قايل لهم: \nاعملوا إللي تعملوه والله لو كنا ثلاثمائة رجل لنسيب لكم البلد أو نطلعكم إنتم منها\nفوهم عمالين يتخانقوا كده عدى عليهم رجل كبير في السن من سادات مكة هو العاص بن وائل، شاف المنظر ...عمر بينضرب\n...فقال لهم إيه إللي حصل \nفقالوا له : صبأ عمر \nفقال لهم : وإنتم مالكم \n...واحد اختار لنفسه حاجة إيه إللي يدخلكم في الموضوع\nإنتم مفكرين إن قبيلته هتسيبكم كده عادي من غير ما تنتقم منكم...اتركوه\nفتركوا عمر وبدأ عمر يجهر بالإسلام في كل مكان محدش يقدر يتعرض له بأذى\nوكان عمره يوم ما أسلم...المفاجأة : ستة وعشرين سنة \nيقول عبد الله بن مسعود وكان من الصحابة الأوائل في الإسلام: إسلام عمر كان فتح لنا \nمكنش حد فينا من المستضعفين يقدر يصلي عند الكعبة،\nأول ما أسلم عمر راح على طول صلى عند الكعبة،\n فقريش ضربوه،\nفضربهم لحد ما فرض نفسه عليهم وبقى يصلي والمسلمين وراه يصلوا ومحدش يقدر يتعرض لهم بأذى\n¤ملحوظة مهمة\nالقصة المشهورة بتاعة إن عمر راح لأخته فاطمة البيت غضبان لما عرف إنها أسلمت مع زوجها وسمعهم بيقرأوا القرآن ودخل عليهم وضربهم وبعدين طلب يقرأ القرآن واغتسل وقرأ آيات سورة طه وبعدين راح لرسول الله ﷺ دار الأرقم وأسلم.\nالقصة دي لا تصح متنا ولا سندا\nمع إنها مشهورة وفي خطباء كتير بيقولوها لكن للأسف غير صحيحة، \n《وهتلاقوا التفصيل في كتاب: ما شاع ولم يثبت في السيرة النبوية 》\nدلوقتي الوضع اختلف بعد إسلام عمر وحمزة فهل الأوضاع هتستقر للمسلمين في مكة ويبدأ الفرج ولّا هتشتد الأمور أكثر؟\nده إللي هنعرفه الجزء الجاي إن شاء الله \n☆#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_الثانية_والعشرون\n#بين_هجرة_الحبشة_الأولى_والثانية\nوقفنا المرة إللي فاتت عند إسلام عمر بن الخطاب وشوفنا إنه من بعد ما أسلم على طول راح نشر إسلامه في مكة كلها\nوكان سبب في إن المسلمين المستضعفين يصلوا عند الكعبة،\nويُقال في رواية فيها ضعف:\n إنه لما أسلم قال لرسول الله ﷺ:\nيارسول الله مش احنا على الحق وهمّ على الباطل؟\nفرسول الله قال له: نعم.\nفقال عمر :طيب ليه نستخبى منهم  خلينا نظهر إسلامنا\nوخرج المسلمين صفين في مقدمة الصف الأول حمزة بن عبد المطلب،\nومقدمة الصف الثاني عمر بن الخطاب ويتقدمهم رسول الله ﷺ،\nفلما كفار مكة شافوهم اتغاظوا واتنكدوا جدا \n《من كتاب: ما شاع ولم يثبت في السيرة النبوية》\nالمهم إن الكفار أكيد اتنكدوا بإسلام حمزة وعمر وده إللي يهمنا\nواستمر أذى المشركين للمسلمين لكن أخف من الأول ،\nوكان رسول الله ﷺ بيدعوهم ويقرأ عليهم القرآن،\nفي مرة لما كان رسول الله ﷺ بيدعو سادات مكة،\nجاء له رجل من الصحابة اسمه عبد الله بن أم مكتوم وهو ابن خال خديجة زوجة رسول الله ﷺ،\nوكان رجل أعمى، وكان عايز يسأل رسول الله عن آيات من القرآن سمعها،\nفكان طول ماهو ماشي بيسأل أين محمد ...أين رسول الله؟...فالناس تقول له كمل في طريقك،\nوهو عمال يمشي بسرعة كأنه بيجري مع إنه أعمى\nوأصلا الأعمى لما بيمشي لوحده بيضرب بالعصاية بتاعته ضربة على اليمين وضربة على اليسار ،\nوضربة أمامه عشان يعرف يمشي خطوة\nفتخيلوا شدة حماسه عشان يسمع القرآن من رسول الله ﷺ \nفلما قرب منه وسأل الناس أين رسول الله قالوا له:\nهو هناك أمامك،\n فلما وصل عنده سمع صوت رسول الله ﷺ بيتكلم مع  واحد من سادات مكة هو الوليد بن المغيرة وقيل أُبَي بن خلف،\nفقال لرسول الله ﷺ:\nيارسول الله علمني مما علمك الله. عايزه يعلمه القرآن ،\nوكان رسول الله ﷺ زي ماتقولوا كده مركز مع الوليد في الدعوة \nفعبد الله بن أم مكتوم أعمى،\nفمش شايف الموقف عشان يقدر يحكم،\nهل المناسب إني أمشي ولّا المناسب إني أسأل وأفضل مستني لحد ما رسول الله ﷺ يجاوبني\nفعبد الله بن أم مكتوم فضل يلح على رسول الله ﷺ إنه يقرأ له،\nوكان جاي بسرعة متحمس شاغله إنه يتعلم القرآن من رسول الله ﷺ،\nفهو تخيل إن رسول الله تبسم له وهيبدأ يقرأ عليه القرآن ويجاوب على كل أسئلته\nلكن رسول الله ﷺ اتضايق من كثرة إلحاحه وإنه شغله عن دعوة الوليد إللي كان حاسس إنه بدأ يلين،\nورسول الله ﷺ كان حريص على إسلام سادات مكة،\nلأن الناس هتتبعهم وكمان هيبطلوا تعذيب المسلمين،\nفكل ده كان بيدور في رأس رسول الله ﷺ وبعدين فجأة لقى حد بيقاطعه وبيلح عليه\nفعبس رسول الله في وجه الأعمى يعني كشّر وأعرض عنه وكمل كلامه مع الوليد،\n☆زي مثلا لما نكون بنتكلم مع حد ومندمجين في الكلام في موضوع مهم وخلاص قربنا نقنع إللي الشخص إللي مطلع عنينا ده، فييجي حد ويقاطع الحوار كله ويبدأ يسألنا عن حاجة ويقعد يلح في السؤال، تخيلوا احنا ممكن نعمل إيه في موقف زي ده\nالموقف ده محدش شافه من الصحابة لكن ربنا رآه \nهل الموقف ده يعدي كده عادي؟\nلأ، ربنا أنزل في الموقف ده قرآن يُتلى إلى يوم القيامة\nنزل جبريل على رسول الله ﷺ وقال له:\n\"عَبَسَ وَتَوَلَّى ۩ أَنْ جَاءَهُ الْأَعْمَى ۩ وَمَا يُدْرِيكَ لَعَلَّهُ يَزَّكَّى۩ أَوْ يَذَّكَّرُ فَتَنْفَعَهُ الذِّكْرَى۩\n أَمَّا مَنِ اسْتَغْنَى فَأَنْتَ لَهُ تَصَدَّى۩ وَمَا عَلَيْكَ أَلَّا يَزَّكَّى ۩ وَأَمَّا مَنْ جَاءَكَ يَسْعَى ۩ وَهُوَ يَخْشَى فَأَنْتَ عَنْهُ تَلَهَّى۩كَلَّا إِنَّهَا تَذْكِرَةٌ \"\nفربنا بيرشد رسول الله ﷺ إنه يساوي بين الناس في الدعوة لأن هو عليه البلاغ فقط أما الهداية فهي بيد الله\nفكان لما عبد الله بن أم مكتوم يأتي لرسول الله ﷺ بعد الحادثة دي كان يُكرمه ويتبسم في وجهه ويحسن إليه\nأما بالنسبة لقول رسول الله ﷺ: \n\"مرحباً بالذي عاتبني ربي من أجله\" \nفالحديث ده ضعيف \n☆ممكن هنا حد يسأل سؤال \nيعني كده إن رسول الله أخطأ وهو معصوم\nفاكرين لما اتكلمنا في قصص الأنبياء عن عصمة الأنبياء\nهقولها تاني عشان أفكركم بها وعشان إللي مكنش يعرف يعرف \nوعشان هتحصل معانا مواقف تانية في السيرة فلازم تكونوا فاكرين معنى عصمة الأنبياء\n◇أولا:\nالأنبياء معصومين من الخطأ في تبليغ الوحي سواء خطأ مُتعمّد أو خطأ غير متعمد، ومعصومين من الكفر قبل الوحي وبعده.\n◇ثانيا:\n الأنبياء معصومين من الوقوع في الكبائر.\n◇ثالثا:\nالأنبياء معصومين من الصغائر التي تدل على الخسة زي سرقة لقمة مثلا.\nلكن ممكن يقعوا في الصغائر التي لا تدل على الخسة مع عدم إقرارهم عليها.\nزي آدم عليه السلام لما وقع في معصية الأكل من الشجرة ناسيا، ومستمرش عليها ده تاب واستغفر على طول وربنا قبل توبته.\n\"وَعَصَىٰ آدَمُ رَبَّهُ فَغَوَىٰ ۩ثُمَّ اجْتَبَاهُ رَبُّهُ فَتَابَ عَلَيْهِ وَهَدَىٰ\"\nفالخطأ إللي وقع فيه رسول الله ﷺ هو خطأ بشري عادي لا يتعارض مع حسن خلقه ﷺ،\nفهو بشر بيفرح ويحزن ويغضب وده بيظهر على ملامح الوجه،\nفالموقف ده رسول الله ﷺ معذور فيه وعبد الله بن أم مكتوم معذور هو كمان،\nفهو مش شايف الوضع إللي فيه رسول الله ﷺ عشان يحكم،\nورسول الله ﷺ كره إن كل شوية حد يقاطعه وهو ما صدق إنه الوليد أو أُبي بن خلف بدأ يلين\nفلما حصل الخطأ الغير مقصود ده؛\nربنا أنزل قرآن لتصحيح المسار وإن الأَوْلى هو دعوة وتعليم الشخص المُقبل على الدين بدل التاني المُعرض ومش عايز يسمع أصلا \nالقرآن بصفة عامة كان بينزل آيات متفرقة على حسب المواقف إللي بتحصل زي ما قلنا قبل كده،\n\"وَقُرْآنًا فَرَقْنَاهُ لِتَقْرَأَهُ عَلَى النَّاسِ عَلَى مُكْثٍ وَنَزَّلْنَاهُ تَنْزِيلًا\"\nيعني ربنا بيقول إن القرآن نزل آيات متفرقة عشان رسول الله ﷺ يقرأه على الناس على مهل،\nويتدبروا آياته ويثبت في قلوبهم، وفي بعض سور القرآن كانت بتنزل كلها مرة واحدة ،\nوأغلبها السور القصيرة زي العصر وزي الكافرون والمسد والفاتحة والإخلاص و...و...\nومنها سورة الكوثر \nوكان سبب نزولها إن رسول الله ﷺ مرة كان خارج من باب المسجد وفي نفس الوقت كان العاص بن وائل سيد من سادات قريش داخل، \nيعني واحد خارج والثاني داخل في نفس الوقت\nفقعد يتكلم مع رسول الله ﷺ وكان في ناس من المشركين قاعدين،\nفلما خلص العاص بن وائل مع رسول الله ﷺ راح قعد معاهم فسألوه : إنت كنت بتكلم مين\nفقال لهم : ده كان الأَبْتر\n☆وكانوا بيسموا إللي معندهوش ابن بالأبتر ورسول الله ﷺ كان مات ابنه القاسم وعبد الله لو تفتكروا \nفربنا أنزل :\n\"إِنَّا أَعْطَيْنَاكَ الْكَوْثَرَ۩فَصَلِّ لِرَبِّكَ وَانْحَرْ۩إِنَّ شَانِئَكَ هُوَ الْأَبْتَرُ \"\nفدي كانت بشارة لرسول الله ﷺ بأن ربنا أعطى له في الآخرة نهر اسمه الكوثر قال رسول الله ﷺ للصحابة عنه:\n\" أَتَدْرون ما الكوثرُ؟ ..فقلنا: اللهُ ورسولُه أعلم \nقال: فإنه نهرٌ وعَدنِيه ربي عزَّ وجَلَّ، عليه خيرٌ كثيرٌ، و حوضٌ تَرِدُ عليه أمتي يومَ القيامةِ، \nآنيتُه عدد النجومِ، فيَخْتَلِجُ العبدُ منهم، فأقولُ: ربِّ، إنه مِن أمتي، فيقول: ما تدري ما أَحْدَثَتْ بعدَك\"\nفالخير ده مستنيك يا محمد في الآخرة أما شانئك يعني مبغضك هو الأبتر يعني هو المقطوع عن كل خير في الدنيا والآخرة\nوهنتكلم عن وصف النهر ده بالتفصيل إن شاء الله واحنا بنتكلم عن الإسراء والمعراج\n☆من الحاجات العجيبة بقى إللي لاحظتها إن الكفار مهما آذوا رسول الله سواء بالشتيمة أو الضرب أو الإهانة...كان رسول الله ﷺ يرجع يكلمهم ويدعوهم عادي \nلأ، وهم يكلموه برده بعدها ولا كأنهم عملوا حاجة\nودول كفار مش واحد مسلم بيدعو أخوه المسلم\nأظن محتاجين وقفة كبيرة أوي مع نفسنا \nمن السور التي يُقال إنها نزلت مرة واحدة ويُقال نزلت آيات متفرقة سورة النجم،\nوكان المشركين بيقولوا: محمد يقول القرآن وبيخترع الكلام\nفأنزل الله:\n\"وَالنَّجْمِ إِذَا هَوَىٰ۩ مَا ضَلَّ صَاحِبُكُمْ وَمَا غَوَىٰ۩ وَمَا يَنطِقُ عَنِ الْهَوَىٰ۩إِنْ هُوَ إِلَّا وَحْيٌ يُوحَىٰ۩ عَلَّمَهُ شَدِيدُ الْقُوَىٰ\"\nمن خلال سورة النجم يهمنا قصتين حصلوا\n◇القصة الأولى:\nفاكريييين عتيبة بن أبي لهب\nاتكلمنا عنه في البداية لما طلق بنت من بنات رسول الله ﷺ إللي كان متزوجها\nلما قرأ رسول الله ﷺ على المشركين في مكة الآيات:\n\"ثُمَّ دَنَا فَتَدَلَّى۩ فَكَانَ قَابَ قَوْسَيْنِ أَوْ أَدْنَى\"\nوسمع الآيات عتيبة بن أبي لهب، \nفكان خارج في تجارة للشام مع أبوه، فراح قايل والله لأروح لمحمد وأؤذيه،\nوجاء عتيبة لرسول الله ﷺ فعلا وقال له إنه بيكفر بالذي دنا فتدلى...إللي هو رسول الله ﷺ يعني،\nثم تَفَل في وجه رسول الله ﷺ\nلكن البَصق مجاش في وجهه الكريم ﷺ،\nفقال رسول الله ﷺ:\nاللهم سلّط عليه كلبًا من كلابك \nيُروَى إن أبو طالب كان حاضر الموقف وسمع دعوة رسول الله ﷺ فاتخض \nفراح وراء عتيبة وقال له دعوة رسول الله ﷺ وسمعهم أبو لهب،\nأو إن عُتيبة لما سمع الدعوة ورجع لأبي لهب قال له على إللي حصل فخاف أبو لهب على ابنه،\nفوهمّ في الطريق نزلوا في مكان عشان يباتوا فيه،\nوالمكان ده كان فيه صومعة لراهب،  فالراهب بص عليهم الصومعة وقال لهم إن المنطقة دي فيها أسود\nفأبو لهب قال للناس إللي كانوا معاه، \nيا جماعة ساعدوني أحمي عتيبة لأني خايف عليه من دعوة محمد\nفجمعوا أحمالهم والمتاع بتاعهم وحطوا عليه عتيبة عشان ينام فوقه وهم ناموا حوله،\nفجاء أسد وقعد يشم وجوههم واحد واحد لحد ما وصل لعتيبة فوق الأمتعة ونط عليه فضربه بمخالبه ومشي،\nوعتيبة صرخ: قتلني.\nومات في مكانه\nفلما أبو لهب عرف قال: مش قلت لكم أنا خايف عليه من دعوة محمد\n\" إِنَّا كَفَيْنَاكَ الْمُسْتَهْزِئينَ\"\n☆الواحد بيتعجب من الناس دي بجد\nيعني عارف إن دعوة محمد ﷺ مستجابة وإنه على الحق، \nومع ذلك مفكرش إنه يسلم \n\"وَجَحَدُوا بِهَا وَاسْتَيْقَنَتْهَا أَنفُسُهُمْ ظُلْمًا وَعُلُوًّا\"\n¤ممكن حد يسأل هنا سؤال\nإزاي رسول الله ﷺ يدعو عليه وهو إللي قال لما الصحابة قالوا له: \nادعُ على المشركين ، فقال رسول الله:\n\"إني لم أبعث لعانا إنما بعثت رحمة\" \nده فعلا كان هدي رسول الله ﷺ، إنه مكنش بيدعي على حد، ولكنه في نفس الوقت كان يدعو على من يأس من إسلامه واشتد عداءه للمسلمين،\nزي نوح عليه السلام لما دعا على قومه ، \nهو دعا عليهم بعد ما ربنا أخبره إن محدش تاني هيؤمن غير إللي آمن معك ،\nفاحنا حتى يجوز إننا ندعو على الظلمة والطغاة بالهلاك،\n إذا كان أذاهم شديد على المسلمين ، ولا يُرجى منهم الهدى أو صلاح الحال \n♡وفي هنا حكم شرعي مهم في من يشتم رسول الله ﷺ،\n ممكن ناس كثيرة يتفاجؤوا به \nأي أحد يشتم رسول الله ﷺ فهو كافر مرتد خارج عن الإسلام سواء كان بيهزر ولا بيتكلم جد ،\nوحدّه القتل سواء كافر أو مسلم،\nحتى لو المسلم تاب فهو يُقتل حدًّا لو وصل أمره للقاضي أو الحاكم، \nوده قول جمهور العلماء من المذاهب الأربعة المعتمد على الدليل من القرآن والسنة\nاتفاجئتم صح\nالسؤال دلوقتي إللي عندكم ...طيب ماهو تاب والتوبة بتمسح ما قبلها ، ده حتى المرتد ربنا بيتوب عليه..ومقام ربنا أعلى من مقام النبي،\nوكمان رسول الله ﷺ كان بيعفو عن إللي كان بيشتمه فاحنا بقى مش هنعفو\nالكلام ده كله صحيح \n إلا في حق رسول الله ﷺ\n◇أيوة التوبة بتمسح إللي قبلها وربنا يقبل التوبة في كل الذنوب والمعاصي لكن في حد من حدود الله،\nزي الرجل المحصن إللي بيزني حده الرجم بالحجارة حتى لو تاب،\nمادام وصل الأمر للحاكم وثبت عليه الزنا وجب إقامة عليه الحد،\nوفي مذهب الإمام أحمد كمان إن إللي يسب رسول الله وتاب لا تُقبل توبته تخيلوا\nفتوبة من يَسب رسول الله ﷺ تنفعه بينه وبين ربه فيكون مسلما مؤمنا،\nويدخل الجنة لكن لا يرتفع الحد عنه فيُقتل مسلما ويُغسل ويُكفن ويُصلي عليه المسلمون\nطبعا كل ده لو وصل الموضوع للحاكم، \nلو موصلش يبقى يتوب بينه وبين نفسه ويعمل الأعمال الصالحة،\nأما بقى لو متبش فده كافر مرتد مفيش كلام\n◇مقام ربنا أعلى من النبي وربنا بيغفر وده حق ربنا،\nلكن رسول الله ﷺ لو الناس شتمته وتابت وشتمته وتابت بقى عِرضه مُستباح لأي حد يشتمه\n◇وهو أه كان بيسامح وده حقه..لكن رسول الله ﷺ مش موجود دلوقتي فمش من حق أي حد إنه يسامح بداله\nهو لو واحد شتمك ولّا أهانك وجه واحد صاحبك قال للي شتمك ده إنه مسامحه بالنيابة عنك وانت مش موجودة ،\nهيكون رد فعلك إيه؟\nعلى الأقل هتقول مين قال لك تتكلم مكاني وبلساني \nورسول الله ﷺ كان بيسامح عشان أسباب شرعية زي إن عشان لا ينتشر بين الناس إن محمد يقتل أصحابه،\nأو من باب تأليف القلوب\nطبعاااااا الحدود دي الحاكم هو إللي يطبقها مش عوام الناس\nعشان محدش يفهم الكلام غلط ويعك الدنيا\n☆أنا جبت لكم المختصر المفيد..إللي عايز يتوسع ويعرف الأدلة بالتفصيل يراجع موقع الإسلام سؤال وجواب ،\nأو كتاب:\n《الصارم المسلول في تَحتُّم قتل ساب الرسول》\n لشيخ الإسلام ابن تيمية.\n◇نرجع للقصة الثانية إللي معانا النهاردة ومرتبطة بسورة النجم، وهي إن رسول الله ﷺ راح عند الكعبة وسادات قريش قاعدين فقرأ عليهم الآيات:\n\"وَأَنَّ إِلَى رَبِّكَ الْمُنْتَهَى۩.... *فَبِأَيِّ آلَاءِ رَبِّكَ تَتَمَارَى ۩هَذَا نَذِيرٌ مِنَ النُّذُرِ الْأُولَى ۩ أَزِفَتِ الْآزِفَةُ ۩\n لَيْسَ لَهَا مِنْ دُونِ اللَّهِ كَاشِفَةٌ ۩ أَفَمِنْ هَذَا الْحَدِيثِ تَعْجَبُونَ ۩ وَتَضْحَكُونَ وَلَا تَبْكُونَ ۩ وَأَنْتُمْ سَامِدُونَ ۩ فَاسْجُدُوا لِلَّهِ وَاعْبُدُوا \"\nفسجد رسول الله ﷺوسجد المسلمون إللي كانوا معاه، وسجد كفار مكة إللي سمعوا الآيات وسجد الإنس والجن...أي حد سمع الأيات سجد وراء رسول الله ﷺ\nمن شدة تأثير آيات القرآن عليهم مكنوش واعيين لنفسهم لدرجة إنهم سجدوا \nتخيلوا رسول الله ﷺ بيقول : \n\"إن من البيان لسحرا\"\nفما بالكم بالقرآن.. وإللي بيقرأه رسول الله ﷺ وبيقرأه على أهل اللغة إللي في إيدهم اللغة العربية الفصحى دي زي العجين،\nيعني فاهمين كل كلمة بتتقال\nلما قاموا وفاقوا من إللي عملوه قالوا : سحرنا محمد \nواحنا مش هنؤمن به أبدا\nوانتشرت الأخبار إن مكة أسلمت \nلحد ما وصلت الأخبار للمسلمين في الحبشة ففرحوا وجمعوا حاجتهم ورجعوا لمكة،\nورجعوا لمكة دي يعني ركبوا البحر أيام وليالي ومشيوا في الطريق أيام وليالي يعني \nتخيلوا المجهود والمشقة إللي تحملوها بسبب شائعة \nوأول ما وصلوا عند مكة استنوا لحد بالليل وأرسلوا واحد يستكشف لهم الموضوع،\nواكتشوفوا إن الخبر كان إشاعة\nاتفقوا إنهم يقسموا نفسهم ثلاثة أقسام: \nقسم يرجع للحبشة، وقسم يدخل مكة يخلص شوية حاجات محتاجينها من غير ما أحد ياخد باله،\nوالقسم الثالث هيدخل مكة عادي قصاد لكن في جِوار حد من سادات قريش عشان يقابل رسول الله ﷺ ويحكوا لهم عن إللي حصل معاهم في الحبشة\nوفعلا رجع الأغلبية للحبشة وبقي بعض الأفراد دخلوا مكة، وتقابلوا مع رسول الله ﷺ وحكوا له الأحداث إللي حصلت معاهم،\nكفار مكة كانوا خفّوا التعذيب عن المسلمين شوية بعد إسلام حمزة وعمر،\nلكن بعد ما حصلت حادثة سجودهم مع رسول الله ﷺ اشتدوا في تعذيب المسلمين تاني\nعايزين يثبتُوا للناس إنهم متبعوش محمد وإنه هو إللي سحرهم\nده غير إن المشركين عرفوا إن المسلمين إللي هاجروا للحبشة عايشين هناك مرتاحين من غير مشاكل والنجاشي استقبلهم استقبال حافل،\nفكل ده غاظ الكفار فبدأوا يصبوا غضبهم في تعذيب المسلمين،\nهنا رسول الله ﷺ أمر المسلمين بالهجرة مرة ثانية للحبشة،\nلكن للأسف المرة دي الموضوع صعب\nقريش مفتحة عينها وحاطين حراس في كل مكان عشان محدش يقدر يطلع  برة مكة من المسلمين أو حتى المشتبه فيهم إنهم مسلمين أو حتى إللي بيفكروا في الإسلام \n☆سبحان الله فعلا ما أشبه اليوم بالبارحة\nوطبعا السؤال إللي بيطرح نفسه هنا...هو ليه أهل مكة مضيّقين على المسلمين كده\nمش المفروض يسيبوهم يطلعوا برة البلد\nهم هيسيبوا لهم البلد يشبعوا بيها ويمشوا ..أهل مكة بقى زعلانين ليه بقى\nآاااااا....إن شاء الله نجاوب على السؤال ده المرة الجاية\n ونشوف مع بعض هل المسلمين هيقدروا يخرجوا برة مكة ولّا لأ"}, {"n": 53, "l": "الجزء 23 | هجرة الحبشه الثانيه | وفد عمر بن العص للنجاشي | والجزء 24 | فشل وفد عمر بن العاص", "u": "", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية_\n#الحلقة_الثالثة_والعشرون\n#الهجرة_الثانية_للحبشة\n#وفد_عمرو_بن_العاص_للنجاشي\nكنا واقفين المرة إللي فاتت عند المسلمين لما رجعوا مكة بعد ما سمعوا إشاعة إن مكة أسلمت،\nواضطروا إنهم يرجعوا تاني للحبشة ويعدّوا الصحراء والبحر إللي هم كانوا لسه راجعين منها\nمجرد التفكير في الموقف صعب... الواحد بعد ما بيمشي مشوار أو حتى بيركب،\nوبيفتكر إنه نسي حاجة محتاجها ولازم يرجع بيبقى على آخره ومتضايق\nدول بقى شايلين عيالهم وحالهم ومالهم على جمال وماشيين أيام وليالي والمفروض إنهم ما صدقوا وصلوا عشان يستريحوا،\nيلاقوا إن الخبر إللي قطعوا بسببه الطريق ده كله كاذب\nوكان المفروض إنهم يبعثوا واحد منهم يروح يتأكد،\n بدل ما يقطعوا المسافة دي كلها\n☆وده يعلمنا إننا مناخدش أي قرار إلا لما نتأكد من صحة الكلام إللي وصل لنا\nأكثر حاجة مضيعانا هي إننا بنمشي وراء الشائعات، \nتلاقي الواحد مجرد ما يسمع كلام من هنا ولا من هنا ينشر ويبدأ يأخذ قرارات، \nده غير بقى السيئات إللي الواحد بياخدها بسبب الشتيمة إللي بيقولها لو الشائعة فيها حاجة تضايقه\nفاتعلموا إنكم قبل ما تصدقوا أحد اتأكدوا من المعلومات الأول منها ومن صحتها\nقلنا إن معظم المسلمين رجعوا للحبشة ودخل بعض الصحابة لمكة، فيهم إللي دخل مكة من غير ماحد يحس بيه،\nوفيهم إللي دخل عادي قصاد أهل مكة زي عثمان بن عفان وزوجته رقية بنت رسول الله ﷺ،\nوقلنا إن كفار قريش اشتدوا في العذاب على المسلمين ومنعوهم حتى إنهم يهاجروا برة مكة،\nووقفنا عند سؤال مهم وهو :\nليه أهل مكة ميسيبوش المسلمين يخرجوا برة مكة وبكده يرتاحوا منهم\nوده مش خاص بأهل مكة ده أي كفار أو ظلمة على مر التاريخ عندهم نفس الفكر،\nيعذبوا المسلمين أو يقتلوهم ولا إنهم يسيبوهم يخرجوا برة البلد\nالسبب في كده:\n◇أولا:\nكفار قريش عارفين إن المسلمين راحوا الحبشة مش عشان يعيشوا حياة الترف هناك وانتهى الموضوع على كده،\nدول راحوا عشان يربوا نفسهم تربية إيمانية مضبوطة فيقدروا يرجعوا لمكة وهم أقوى،\nوكفار قريش عارفين إن رسالة الإسلام رسالة عامة يعني مش خاصة بأهل مكة بس،\nيعني المسلمين هيعملوا كل إللي يقدروا عليه لنشر دعوة الإسلام في الأرض كلها،\nوأكيييييد هيرجعوا لمكة في يوم من الأيام\nفعلى إيه بقى وجع القلب ده...احنا نحبسهم ولّا نقتلهم ولّا نعذبهم من البداية لحد ما يعترفوا على نفسهم بحاجات غير صحيحة ويتركوا الدين\n☆يارب نكون بنربط بين الأحداث وفاهمين الليلة ماشية إزاي \n◇ثانيا:\nفي علاقات دوبلوماسية بين مكة والحبشة...فكده المسلمين هيغيروا العلاقات دي لصالحهم وتضيع مصالح مكة مع الحبشة،\nلأن أهل الحبشة هيشوفوا أخلاق المسلمين وتعاملاتهم وإنهم لا يستحقوا التعذيب والقتل،\nفكده هيعرفوا إن أهل مكة هم إللي ظلمة وهيستنكروا جدا أفعالهم وشكلهم هيبقى وحش قصاد ملك الحبشة،\nوممكن الموضوع يتطور لقطع العلاقات السياسية والاقتصادية بين مكة والحبشة،\nوده مش في صالح مكة إطلاقا وهيضرهم جدا \n☆واخدين بالكم\n◇ثالثا:\nكفار مكة خافوا إن أهل الحبشة يُسلِموا وخصوصا إنهم عارفين إن دعوة الإسلام مُقنعة والقرآن كلام مُعجِر،\nفسهل إن الناس تدخل في الإسلام،\nفلو دخلوا في الإسلام ممكن يأتون بجيش لغزو مكة\nوهم ملهمش طاقة بحرب ملك الحبشة\nده مقدروش يقفوا في وجه أبرهة إللي كان مجرد تابع للنجاشي، هيقفوا قصاد النجاشي\nيبقى نريح دماغنا من البداية ونمنع المسلمين من السفر ونحبسهم ونعذبهم ويا دار مدخلك شر \n☆بس على مين ...ويمكرون ويمكر الله..الناس دي مش قادرة تفهم إنها بتحارب ربنا، \nومهما كان لهم الغلبة والنصر في البداية فالعبرة دائما بالنهاية...والأيام بيننا \nبسبب تزايد تعذيب الكفار للمسلمين، والخوف عليهم من القتل،\nرسول الله ﷺ أصدر قرار بالهجرة للمرة الثانية للحبشة،\nلكن الهجرة المرة دي كانت أصعب\n◇أولا : \nقريش بقوا واخدين بالهم ومراقبين المسلمين وحاطين حراس في كل مكان\n◇ثانيا:\n المرة دي الناس إللي هتخرج ناس مهمة جدا،\nزي أم حبيبة رملة بنت أبي سفيان، زعيم من زعماء مكة الكفار\nوأبو حذيفة بن عتبة بن ربيعة وأبوه عتبة من سادات قريش  الكفار\nوفِراس بن النضر بن الحارث\nفاكرين النضر بن الحارث إللي راح اتعلم قصص فارس والروم كان بيقعد يقول للناس أنا بحكي لكم أساطير ومحمد بيحكي لكم أساطير ،\nوهو إللي أدخل في مكة الضرب على العود...تخيلوا ابنه أسلم\nوهشام بن العاص بن وائل إللي أبوه العاص بن وائل كان بيقول عن رسول الله ﷺ إنه أبتر\n☆شوفتم مكر ربنا بالكفار\nهم لم يؤمنوا وحاربوا دعوة الإسلام فأخرج الله من بيوتهم ومن أصلابهم من يؤمن بالله،\nيعني إللي هينصر الدعوة إللي إنت بتحاربها هم أحب الناس لقلوبكم\nبجد أي قهرة المشركين كانواحاسين بها في الوقت ده...سبحان الله\n◇ثالثا:\n العدد إللي هيخرج للحبشة المرة دي أكبر بكثير من المرة الأولى،\nتقريبا نصف المسلمين إللي أسلموا هيخرجوا من مكة\nهيخرج ثلاثة وثمانون رجل وتسعة عشرة امرأة، غير الأطفال،\nفتخيلوا لما أبناء الزعماء نفسهم يخرجوا من مكة شكلهم  قصاد الناس هيبقى عامل إزاي\nومكة بلد صغير فخروج العدد الكبير ده مرة واحدة هيعمل قلق جامد في مكة\nتصوروا لما أهل مكة يصحوا ثاني يوم ويلاقوا نقص منهم حوالي مائة شخص\nصدمة جامدة طبعا لهم\n لكن رسول الله ﷺ مع كل الصعوبات دي فهو كقائد عنده فقه واقع شاف إن الدعوة لن تصل للناس إلا عن طريق الدعاة،\nوالدعاة وصلوا لمرحلة من الإيذاء الشديد خلتهم مش عارفين يمارسوا الدعوة،\nيبقى لازم القرار الحاسم والجريء بخروج المسلمين من مكة\nفي شباب ممكن يتحمسوا في مرحلة زي دي من مراحل الدعوة ويقولوا :\nلأ ..واحنا نسيب لهم البلد ونمشي ليه...احنا هنفضل ثابتين مهما كانت النتائج حتى لو متنا\nوده خطأ... شوفوا ربنا خلق النبات الضعيف لين ومرن،\nعشان لما الريح الشديدة تيجي عليه،\nيميل ومينكسرش، لحد ما يكبر ويبقى شجرة قوية لها جذور عميقة في الأرض،\nمهما اشتدت الريح عليها لا تميل وتظل ثابتة\nوكذلك المؤمن يستغل الأمور لصالحه لحد ما يبقى قوي ويقدر يواجه\nوهو ده إللي رسول الله ﷺ عمله،\nوهنشوف في النهاية سياسة رسول الله ﷺ وصلت المسلمين لإيه\nالمسلمين بدأوا يخططوا إزاي هيخرجوا من مكة، وكان القائد بتاعهم هو جعفر بن أبي طالب ابن عم رسول الله ﷺ،\nفبدأوا يشوفوا المخارج والمداخل المناسبة عشان يخرجوا من مكة والكل اشترك في إنجاح مهمة الهرب \nفمطلوب الأخذ بالأسباب إللي يقدروا عليها وفي نفس الوقت يتوكلوا على الله\nوفعلا اتسللوا في الليل وقدروا يهربوا ويوصلوا للبحر ويركبوا السفن واتجهوا للحبشة ومحدش من الكفار قدر يمسك منهم أحد\n\"إنَّ اللَّهَ يُدَافِعُ عَنِ الَّذِينَ آمَنُوا\"\nأهل مكة يسكتوا ويقولوا خلاص بقى كفاية كده وخلونا ننهي الأزمة والصراع ده...لأ\nهم مش هيسكتوا ولا هيتنازلوا غير لما يتنازل المسلمون عن دينهم، \nودي سنة كونية مش هتتغير مهما سمعتم من كلام أهل الباطل وإنهم عايزين يحافظوا على البلد واستقراره\n\"وَلاَ يَزَالُونَ يُقَاتِلُونَكُمْ حَتَّىَ يَرُدُّوكُمْ عَن دِينِكُمْ إِنِ اسْتَطَاعُواْ\"\nعملوا إيه بقى\nاحنا عارفين إنهم ميقدروش يحاربوا الحبشة، وكمان في علاقات طيبة بينهم مش عايزين يخسروها،\nقالوا بس مفيش غير إننا نقعد مع ملك الحبشة على ترابيزة المفاوضات\nلكن برده الموضوع مش سهل\nأصل ملك الحبشة وإللي كان اسمه 《أَصْحَمة》 مشهور إنه ملك عادل لا يُظلَم عنده أحد\nفالكلام المباشر مش هينفع لازم الحيلة...طيب مين يا جماعة عندنا أكثر واحد ذكي عندنا ويقدر يستخدم الحيلة ويقنع النجاشي\nمفيش غيره أَرْطَبُون العرب\n《عمرو بن العاص بن وائل》 \nأخو هشام بن العاص إللي أسلم وهاجر للحبشة\nوعمرو بن العاص من دُهَاة العرب الأربعة \n☆الأرطبون كلمة معناها الرجل الداهية شديد الذكاء، وهي مأخوذة من كلام الرومان، فهم كمان كان عندهم أرطبون\nفمالوضوع بالنسبة لعمرو بن العاص مش بس مهمة رسمية من قريش،\n لأ ده كمان الموضوع قضية شخصية يعني هيقدر يتكلم بقلب جامد،\nومش بس كده ده عمرو بن العاص صديق شخصي للنجاشي،\nيعني مفيش أي أحد أنسب من عمرو\nواختاروا مع عمرو واحد اسمه عبد الله بن ربيعة وهو برده أخو عباس بن ربيعة من الصحابة إللي هاجروا للحبشة،\nكده الخطوة الأولى تمت، \nالخطوة الثانية مينفعش يدخلوا على الملك بإيدهم فاضية\nفأهل مكة راحوا واشتروا الهدايا الثمينة وبالذات الجلود، لأنهم كانوا عارفين إن النجاشي والحاشية بتاعته بيحبوا الجلود،\n☆شوفوا بيصرفوا فلوس ومرتبات بمئات الآلاف والملايين أد إيه عشان مهمة واحدة بس إنهم يصدوا عن سبيل الله ويضلوا الناس بتضليلهم وكذبهم\n\"إِنَّ الَّذِينَ كَفَرُوا يُنْفِقُونَ أَمْوَالَهُمْ لِيَصُدُّوا عَنْ سَبِيلِ اللَّهِ فَسَيُنْفِقُونَهَا ثُمَّ تَكُونُ عَلَيْهِمْ حَسْرَةً ثُمَّ يُغْلَبُونَ \"\nالمهم عمرو بن العاص وعبد الله بن ربيعة أخذوا الهدايا وطلعوا عالحبشة،\nهم كمان مشيوا ليالي وأيام وركبوا البحر وتحملوا مشقة السفر زيهم زي المسلمين،\nلكن هل أجر وفد قريش زي أجر الصحابة المهاجرين\nالكفار بيتألموا والمسلمين بيتألموا نفس الألم لكن المسلمين يرجون الأجر والثواب من الله\n\"إِنْ تَكُونُوا تَأْلَمُونَ فَإِنَّهُمْ يَأْلَمُونَ كَمَا تَأْلَمُونَ وَتَرْجُونَ مِنَ اللَّهِ مَا لا يَرْجُونَ \"\nوصل عمرو بن العاص الحبشة، لكنه مدخلش على النجاشي على طول\nدخل على البَطَارِقة إللي هم كبار رجال الحكم من النصارى إللي بيقعدوا مع النجاشي ، الحاشية يعني\nفلما دخل عليهم وهم طبعا عارفينه...فرحبوا به وأعطاهم الهدايا الثمينة إللي كان جايبها معاه،\nوبكده ضمن إن البطارقة هيكونوا في صفه لما يتكلم مع النجاشي،\nوحتى لو هم مش هيبقوا في صفه فهو على الأقل خلاهم على الحياد\nيعني هل من المعقول إني أكون لسه جايب لكم هدايا أد كده وبعدين لما أطلب حاجة هتعترضوا\nوالمثل بيقول إيه \nاطعم الفم تستحي العين\n☆هو كان داهية العرب من شوية \nركزوا بقى واتعلموا منه، عشان لما تكونوا عايزين من حد حاجة تتبعوا الخطوات إللي هو عملها \nدخل عمرو بن العاص على النجاشي وسلموا على بعض  وأعطى له الهدايا أصحاب بقى \nولكم أن تتخيلوا الموقف والناس كلها مبسوطة والدنيا ماشية تمام\nكده الجو مُهيأ إنه يتكلم في الموضوع إللي هو جاي عشانه،\nشوفوا اختياره للكلام، هو مقلش للنجاشي وش كده هات المسلمين إللي عندك،\nلأ...هو بدأ يختار الألفاظ إللي هيقولها للنجاشي عشان يقنعه\nقال عمرو للنجاشي:\nأيها الملك! في شوية غِلمان سفهاء كده طلعوا انفصلوا عن مكة وجاؤا بلدك\n《وده أول سهم يضربه عمرو\n..فهو لما يحقر من المسلمين مع إنهم كلهم من السادة فكأنه بيقول له إنت مش هتقدم كلام السفهاء على وفد قريش الرسمي\n》\n كمّل عمرو: \nوهم تركوا دين قومهم وحتى مدخلوش دينك \n《السهم الثاني...يعني هم مش عاجبهم دين قومهم ولا حتى عاجبهم دين الرجل إللي استضافهم في بلده\n》\nوجاء والسهم الأخير.. قال : \nوأنا مُرسل لك من أشراف وزعماء مكة إللي هم أصلا آباءهم وأعمامهم وهم أدرى الناس بهم عشان ترجعهم معايا \nيعني باختصار عمرو بيقول له : \nالزعماء بعتوني عشان ترجع معايا المسلمين، ولو معملتش كده مش هيبقى في هدايا وهيبقى في قطع علاقات ،\nوإنت ممكن تتخدع بكلامهم لكن أهلهم إللي عاشوا معاهم سنين طويلة عارفينهم وحافظينهم،\nفابعثهم معايا وهم يتصرفوا معاهم، وإنت صاحب الأخلاق،\nفلازم الأولاد يرجعوا لآبائهم\nقبل ما النجاشي يرد على عمرو بأي كلمة.. البطارقة إللي كانوا قاعدين تدخلوا وقالوا:\nكلامه صح أيها الملك\nهم قومهم وأعلم بهم سلم المسلمين لعمرو بن العاص وعبد الله بن ربيعة يرجعوهم لقومهم\nطبعا عمرو بن العاص مبسوط جدا دلوقتي ...كله ماشي تمام حسب الخطة \nهو همه كله إن النجاشي ميسمعش من المسلمين، لأنه عارف إن كلام المسلمين مقنع، \nولو سمع النجاشي القرآن هتبقى ورطة \nفرد النجاشي على عمرو وعلى البطارقة وقال:\nلا والله ما أسلمهم إلا لما أسمع منهم\nبقى الناس دي تختار بلدي وحمايتي أنا بالذات وفي الآخر أسلمهم كده من غير ما أسمع منهم \nأنا هرسل لهم يأتون وأسمع منهم وأشوف هل كلام الوفد فيهم صحيح ولّا لأ وبعدين أقرر\n☆إذا جاءك الرجل وقد فُقئت عينه فلا تحكم له حتى ترى الآخر فربما فُقئت عيناه\nلما تسمعوا مشكلة من أحد متتحدفوش وتتعاطفوا معاه من غير لما تسمعوا من الطرف الثاني، \nلأن كل واحد بيحكي من وجهة نظره، لما واحدة تيجي تقولك دي فلانة دي عملت وسوت ولّا حد من عيالك ييجي يشتكي من أخوه، \nولّا أمك بتشتكي لك من أختك ولا زوجة بتشتكي من زوجها ولّا...ولّا....\nاوعوا تحكموا على حد إلا لما تسمعوا من الطرف الثاني هو فعلا قال أو عمل كده أو لأ، \nولو فعلا عمل كده فاعرفوا الدافع والسبب إللي خلاه يعمل كده،\nمش يمكن هو كان رد فعل لظلم وقع عليه، أو بسبب تصرف خاطئ من الشخص إللي بيشتكي\nطيب مش هتعرفوا توصلوا للطرف الثاني\nيبقى الواحد يحط لسانه جوة بؤه ويسكت\nلأن كل كلمة هنقولها هنتحاسب عليها يوم القيامة \nهنقول إيه لربنا لما نعك الدنيا وتحصل مشاكل بسببنا عشان اتكلمنا واحنا مش عارفين حاجة \nبقول تاني\nالسيرة مش حكاية بنتسلى بها ...السيرة دين بنتعلمه عشان نطبقه،\nكل مواقف السيرة بلا استثناء بتتكرر في حياتنا فلازم نأخذ منها الدروس والعبر ونستفيد منها في إزاي نتصرف في المواقف إللي بنواجهها\nإللي مش بيعمل كده...يبدأ يعمل عادي مفيش مشكلة \nفي الوقت إللي النجاشي كان قاعد فيه مع عمرو بن العاص،\nكان وصل للمسلمين إن عمرو بن العاص جاء يزور النجاشي وأكيد جاي عشان يقنع النجاشي إنه يسلمهم له\nفعمل المسلمون زي مجلس شورى سريع بقيادة جعفر بن أبي طالب عشان يشوفوا هيعملوا إيه لما النجاشي يطلبهم،\nفقالوا لبعض:\nهااااه هنقول إيه للنجاشي لو روحنا له\nفقالوا: \nوالله نقول إللي نعرفه وإللي اتعلمناه من رسولنا ويحصل إللي يحصل\n☆ممكن حد يسأل ويقول طيب مش المفروض إنهم يحافظوا على نفسهم من الهلاك زي ما قلنا قبل كده عشان يحافظوا على الدعوة \nأيوة فعلا الداعية بيبذل الأسباب عشان يحافظ على نفسه عشان يوصل الدعوة الصحيحة بدون 《تحريف》،\nلكن لو تعارض تحريف الدين مع حياة الداعية إيه إللي يكون مُقَدم \n \nيعني يا إما أحرف في الدين عشان أرضي البشر وأحافظ على حياتي،\nأو إني أحافظ على الدين في مقابل إن في احتمال إني أفقد حياتي،\nفهنا يُقدم حفظ الدين على حفظ حياة الداعية زي ما الصحابة عملوا\nوخصوصا إنهم مكنوش خايفين من أحد لأنهم عندهم يقين إن دول مجرد بشر وإن إللي بيحرك البشر هو الله\nفلما همّ يطيعوا رب البشر وينصروه ويتوكلوا عليه النتيجة هتكون إيه\nأرسل النجاشي جنود له عشان يأتوا بالمسلمين ويسمعوا منهم،\nراح بعض المسلمين بقيادة جعفر بن أبي الطالب وكانوا متفقين إنه هو إللي هيتكلم،\nلأن هو أصلا رئيس الوفد إللي كان جاي من مكة،\nوكمان هو خطيب، يغني كلامه مترتب فهيقدر يوصل كلام المسلمين بأحسن صورة ممكنة،\nده غير إنه من بني هاشم أشرف أشراف الوفد الإسلامي،\nيعني كأن المسلمين بيردوا بطريقة عملية على عمرو بن العاص بإن احنا مش غِلمان سفهاء زي مانت قلت\n☆شوفتم إزاي المسلمين همهم المصلحة، \nمقعدوش يتخانقوا وكل واحد يقول لا أنا إللي اتكلم وده يقول أنا،\nمش مهم مين يتكلم أهم حاجة إن الرسالة توصل مادام الشخص إللي بيتكلم مُؤهل للكلام\nيارب نفهم \nبدأ الحوار بين النجاشي وجعفر بن أبي طالب وسط اجتماع الوزراء والبطارقة وعمرو بن العاص والموقف مهيب \nسأل النجاشي جعفر سؤال محدد ومباشر:\nإيه هو السؤال\nهنعرف الجزء الجاي إن شاء الله \n#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_الرابعة_والعشرون\n#فشل_وفد_عمرو_بن_العاص\nكنا واقفين المرة إللي فاتت عند النجاشي لما استدعى المسلمين عشان يسمع منهم ويشوف كلام عمرو بن العاص صحيح ولّا لأ،\nوبدأ الحوار بين النجاشي وبين جعفر بن أبي طالب رئيس الوفد،\nالنجاشي أصْحَمة سأل جعفر سؤال واضح ومحدد وقال:\nإيه الدين إللي إنتم فارقتم بسببه قومكم وحتى مدخلتوش في ديني، ولا دين أي أمة من الأمم \n☆السؤال يعتبر غريب شوية صح\nيعني المسلمين في الحبشة بقالهم فترة، لا النجاشي سألهم ولا المسلمين كانوا متحمسين إنهم يدعوا الناس في أرض الحبشة للإسلام،\nكل إللي ملك الحبشة يعرفه عن المسلمين إنهم ناس اتظلموا في بلادهم فلجأوا إليه،\nلكن اتظلموا إزاي وبسبب إيه مكنش مهتم إنه يعرف، عادي يعني بتحصل \nيعني السبب في إن النجاشي سأل عن الدين الجديد ده هو عمرو بن العاص وإلا مكنش النجاشي هيفكر يسألهم عن حاجة\nوحتى المسلمين مكنوش بيدعو في أرض الحبشة فالنجاشي عمره ما كان هيسمع عن الإسلام في الوقت ده خالص \nشوفوا،\nعمرو بن العاص أه أرطبون العرب وعنده مكر ودهاء وهو من دهاة العرب الأربعة،\nلكن هو بيتعامل مع مين...واقف قصاد مين...إنت مكرك يقابله مكر خير الماكرين\nهنشوف إزاي مكر قريش المتمثل في وفد عمرو بن العاص بالمسلمين انقلب عليهم \n◇و بالمناسبة المسلمين مكنوش متحمسين للدعوة في أرض الحبشة لأن هم كانوا عايزين يحافظوا على الدين إللي هم بيحملوه\nلأنهم لو بدأوا يدعوا في أرض الحبشة وهم عدد قليل وقوتهم بسيطة،\nهيفتحوا على نفسهم جبهات هم مش قدها وهيعرضوا نفسهم للأذى وممكن يُقتلوا كلهم\nوهم أصلا هربانين من مكة عشان يحموا الدين، والحبشة كدولة أقوى من مكة بمراحل\n فهنا كان الأَوْلى إن المسلمين يحافظوا على نفسهم من الهلاك في مقابل السكوت عن الدعوة وخصوصا إن ده كان في بدايات الإسلام\nودي حاجة اسمها فقه الواقع وفقه الأولويات،\nيعني المسلمين حللوا الواقع بتاعهم وشافوا الاختيارات إللي قصادهم،\nوبعدين اختاروا الأَوْلى ..يعني عملوا أحسن اختيار من الاختيارات المتاحة قصادهم\nبدأ جعفر بن أبي طالب يجاوب على النجاشي وركزوا في الإجابة كويس\nقال جعفر:\nأيها الملك!\nاحنا كنا ناس أصحاب جاهلية...بنعبد الأصنام ونأكل الميتة ونعمل الفواحش ونُسيء الجوار، والقوي منا بياكل حق الضعيف\n《الأفعال دي مترضاش بها النفوس الكريمة،\n وهنا في إشارة إن عمرو بن العاص لسه على الصورة دي من الجاهلية \nوالمشاكل إللي عرضها جعفر فيها ظلم، إما ظلم للنفس بعبادة الأصنام أو ظلم البشر،\nفتخيلوا لما الكلام ده بيتعرض قصاد ملك عادل لا يُظلم عنده أحد هيكون إحساسه إيه》\nوده كان أول سهم أطلقه جعفر بن أبي طالب\nنشوف السهم الثاني قال:\nفكنا بنعمل كده لحد ما ربنا بعث لنا رسول عارفين أصله وفصل وصدقه وأمانته لدرجة إننا كنا مسميينه الصادق الأمين\n《والنصارى بيؤمنوا بالرسل بصفة عامة وقصص الأنبياء والرسل موجودة عندهم فالكلام عن الأنبياء والرسل بالنسبة لهم حاجة مألوفة》\nالسهم الثالث اتكلم عن الصورة الجميلة المضادة للجاهلية وإللي أصبحوا عليها بعد الإسلام قال:\nدعانا إلى عبادة الله وحده ونسيب إللي كان بيعبده آباءنا وأجدادنا، \nوأمرنا بالصدق وصلة الرحم وحسن الجوار وأداء الأمانة، \nوالكف عن المحارم والدماء،\nونهانا عن الفواحش وقول الزور وأكل مال اليتيم وقعد جعفر يعدد للنجاشي أمور الإسلام،\n☆حطوا نفسكم كده مكان النجاشي وقارنوا بين الوضعين الجاهلية والإسلام ..أي عاقل هيشوف الفرق الواضح جدا بين الصورتين \nكمل جعفر في السهم الرابع وقال :\nفاحنا صدقناه وآمنا به واتبعناه وعبدنا الله وأحللنا ما أحل الله وحرمنا ما حرم الله، احنا معملناش حاجة غلط أهه\nراح قومنا وأهلنا اعتدوا علينا وعذبونا ،\nوفتنونا عن ديننا عشان عايزينا نرجع لعبادة الأصنام ونعمل الخبائث بتاعة الجاهلية تاني\n☆وطبعا الكلام ده ذكّر النجاشي والبطارقة بالتعذيب إللي تعرض له الحواريين أصحاب عيسى عليه السلام ،\nوإللي تناقلته كتب النصارى، فتخيلوا مشاعر الناس إللي قاعدة بتسمع عاملة إزاي\nوالسهم الخامس قال جعفر :\nفلما قومنا قهرونا وظلمونا وشقوا علينا، جينا عندك واخترنا بلدك دونا عن أي بلد تانية، واخترنا حمايتك وكان رجائنا إننا لا نُظلم عندك\n☆خدوا بالكم إن جعفر بن أبي طالب مكنش يعرف عمرو بن العاص قال إيه للنجاشي عن المسلمين،\nلكن عالم الغيب والشهادة يعلم بالضبط إيه إللي حصل\nفشوفوا الردود إللي جعفر قالها،\nفكان بيرد السهام إللي عمرو بن العاص رمى بها المسلمين من غير ما يعرف\nفسبحان من أجرى الكلام على لسانه\n\"وَيَمْكُرُونَ وَيَمْكُرُ اللَّهُ وَاللَّهُ خَيْرُ الْمَاكِرِينَ \"\nكان واضح جدا إن النجاشي والبطارقة إللي معاه تأثروا بكلام جعفر بن أبي طالب،\nلكن النجاشي عاقل ميقدرش يحكم بمشاعره كده وخلاص،\nإنت قلت الكلام ده..فين الدليل على صدق كلامك\nعشان كده النجاشي سأل جعفر:\nمعاك أي حاجة من كلام الرسول إللي بتقول عليه ده\n☆والنجاشي مش مجرد حاكم ده كان عالم من علماء النصارى، فعارف إن كلام الرسل مختلف تماما عن كلام البشر العادي\nولعله كمان كان عارف إن ده زمن نبي زي ما اتكلمنا في البداية خالص إزاي إن أهل الكتاب كانوا عارفين إن زمن رسول الله هو زمن آخر الانبياء\nفجعفر قال له أيوة معايا وسبحان من هدى جعفر إنه يختار الآيات المناسبة ليقرأها على النجاشي\nبدأ جعفر يقرأ:\n\"كهيعص ۩ ذِكْرُ رَحْمَتِ رَبِّكَ عَبْدَهُ زَكَرِيَّا۩ إِذْ نَادَى رَبَّهُ نِدَاءً خَفِيًّا۩ قَالَ رَبِّ إِنِّي وَهَنَ الْعَظْمُ مِنِّي وَاشْتَعَلَ الرَّأْسُ شَيْبًا وَلَمْ أَكُنْ بِدُعَائِكَ رَبِّ شَقِيًّا۩\n وَإِنِّي خِفْتُ الْمَوَالِيَ مِنْ وَرَائِي وَكَانَتِ امْرَأَتِي عَاقِرًا فَهَبْ لِي مِنْ لَدُنْكَ وَلِيًّا...\"\nالنصارى بيسمعوا ويتذكروا قصة زكريا عليه السلام والمعجزة إللي حصلت معاه ...ممكن ترجعوا تقرأوا قصة زكريا في قصص الأنبياء تاني لو حابين،\n عشان تعرفوا مشاعر النجاشي والبطارقة كانت عاملة إزاي وهم بيسمعوا قصته\nتأثر النجاشي والبطارقة لكلام القرآن لدرجة إنهم بَكُوا\nبعد ما خلص جعفر القراءة قال النجاشي:\nإن الكلام ده والكلام إللي جاء به موسى= وفي رواية ثانية جاء به عيسى= ليخرج من مشكاة واحدة، يعني كلام الإثنين من نفس المصدر \nوده إقرار من النجاشي بصدق رسالة الإسلام وصدق رسول الله ﷺ  وصدق المسلمين،\nفنظر النجاشي لعمرو بن العاص وعبد الله بن أبي ربيعة وقال لهما:\nروحوا والله ما أسلمكم المسلمين أبدا\n☆فين هدايا عمرو ..فين تخطيطه...ومكره ودهائه \nفسينفقونها ثم تكون عليهم حسرة ثم يغلبون\nإنت بتحارب ربنا يابني \nخرج المسلمون من عند النجاشي وهم فرحانين حاسين بالأمن، أول هزيمة لقريش \nفي المقابل خرج عمرو بن العاص من عند النجاشي وهو في شدة الغضب والغيظ\nأول مرة ينضرب في كبريائه الضربة القوية دي، داهية العرب إللي عمره خمسة وأربعين سنة يتغلب كده من شاب صغير عمره سبعة وعشرين سنة \nلكن القضية هنا مش سن ..القضية هنا مين إللي بيدافع عن الحق ومين إللي بيدافع عن الباطل،\nفمهما طغى الباطل وانتشر في النهاية الحق هو الغالب\nيسكت عمرو بقى ويرجع لقريش ويسيب المسلمين\nأبدا\nمن شدة غيظه وغضبه قال: \nوالله لأخبر النجاشي بكرة سرهم ولأخليه يستأصلهم ويقتلهم كلهم \nأنا كنت عايز أرجعهم بس لمكة لكن بعد إللي حصل مش هسيبهم \nفصاحبه عبد الله بن أبي ربيعة لما سمع طريقته في التحدي وشاف منظره خاف منه\nوقال له: \nاوعى تعمل كده\nمهما خالفونا فالمسلمين دول أرحامنا...إخوتنا وأبناء أعمامنا \nلكن عمرو مجروح في كبريائه فرفض وقال : \nوالله لأقول للنجاشي إنهم بيقولوا عن عيسى إنه عبد \n☆والموضوع ده كارثة في الحبشة \nلأن عقيدة النصارى في الحبشة إن عيسى عليه السلام هو إله تجسد في صورة بشر ، فإزاي حد يقول على الإله بتاعهم إنه عبد\nوده يدل على دهاء عمرو وأد إيه عنده معلومات كثيرة\nعارف مين هو عيسى وعارف رأي المسلمين فيه ورأي أهل الحبشة،\nفدي نقطة ضعف قاتلة ممكن فعلا تؤدي لقتل المسلمين جميعا \nلكن برده...إنت بتحارب مين ياعمرو \nراح عمرو بن العاص في اليوم الثاني للنجاشي وهو وسط البطارقة وقال له:\nأيها الملك!\nالمسلمين بيقولوا عن عيسى بن مريم قولا عظيما،\nفابعث حد من عندك يستدعيهم واسمع بنفسك بيقولوا إيه\nالنجاشي عارف عمرو ودهائه، وإنه مش هيسكت \n ومع ذلك مقدرش يتجاهل طلبه،\n لأن الموضوع حساس وكمان الكلام كان في حضور البطارقة فممكن تحصل أزمة في البلد،\nفأرسل النجاشي يطلب جعفر بن أبي طالب، تقول السيدة أم سلمة وكانت من الناس إللي هاجرت للحبشة :\nدي كانت أشد حاجة حصلت معانا\nالمسلمين اتورطوا\nرأي الإسلام في عيسى يتعارض مع رأي النصارى تماما،\nوهم ضعفاء لاجئون ومفيش مكان تاني يستقبل المسلمين،\nاجتمع الوفد الإسلامي مع بعض واتشاوروا نعمل إيه\nهنقول إيه في عيسى \nفقالوا بمنتهى الوضوح:\nوالله لنقول فيه ما قال الله..احنا هنألف؟!\nهنقول ويحصل إللي يحصل\n☆القرار ده يعتبر قرار انتحاري...لكن الصحابة عارفين إن حياتهم مش مهمة مقابل الحفاظ على الدين من التحريف،\nيعني مش هيحرفوا الدين عشان يحافظوا على حياتهم\nمفيش حاجة تُقدّم على العقيدة \nوصل جعفر ومعاه الوفد الإسلامي ووقفوا قصاد النجاشي والبطارقة من حوله، سألهم النجاشي:\nماذا تقولون في عيسى بن مريم\n☆موقف صعب ...أي كلمة غلط هتحصل كارثة\nفقال جعفر بمنتهى الثقة:\nنقول فيه إللي جاء به نبينا...عبد الله ورسوله\nوقرأ عليهم :\n\"وَاذْكُرْ فِي الْكِتَابِ مَرْيَمَ إِذِ انْتَبَذَتْ مِنْ أَهْلِهَا مَكَانًا شَرْقِيًّا۩ فَاتَّخَذَتْ مِنْ دُونِهِمْ حِجَابًا فَأَرْسَلْنَا إِلَيْهَا رُوحَنَا فَتَمَثَّلَ لَهَا بَشَرًا سَوِيًّا۩قَالَتْ إِنِّي أَعُوذُ بِالرَّحْمَنِ مِنْكَ إِنْ كُنْتَ تَقِيًّا.....\nقَالَ إِنِّي عَبْدُ اللَّهِ آتَانِيَ الْكِتَابَ وَجَعَلَنِي نَبِيًّا  وَجَعَلَنِي مُبَارَكًا أَيْنَ مَا كُنْتُ وَأَوْصَانِي بِالصَّلَاةِ وَالزَّكَاةِ مَا دُمْتُ حَيًّا۩\n وَبَرًّا بِوَالِدَتِي وَلَمْ يَجْعَلْنِي جَبَّارًا شَقِيًّا...\"\nيعني عيسى وأمه مريم عليهما السلام لهما مكانة عظيمة لكن في النهاية بشر\nالكلام ده كلام خطير جدا\nالنجاشي بيسمع والبطارقة بيسمعوا...الأصوات بدأت تعلى في المكان والمسلمين مستنيين الرد إللي هيحدد مصيرهم لحظات تقطع الأنفاس فعلا\nوفجأة النجاشي يتحرك ويأخذ عود نبات\n من الأرض ويقول كلام محدش أبدا توقعه..لا عمرو بن العاص ولا الوفد الإسلامي ولا حتى البطارقة \nقال النجاشي:\nوالله  ما  عدا  عيسى بن مريم  ما قلت  هذا  العود \nيعني كل الكلام إللي قلته عن وصف عيسى بن مريم صحيح،\nيعني النجاشي اعترف بعبودية عيسى وبنبوته وإنه ليس إله\nالبطارقة مش عاجبهم الكلام وبدأوا يتناخروا\n =يعني يطلعوا أصوات من مناخرهم= وأصواتهم بدأت تعلى بالغضب،\nفالنجاشي صاح بهم بكل حزم : \nوالله وإن نخرتم...كلامه كل صح\nوأخذ النجاشي ثلاثة قرارات محدش كان يتوقعها أبدا\n◇الأول:\nاستضافة المسلمين في الحبشة وإكرامهم غاية الإكرام.\nوالقرار ده خطير لأن البطارقة معترضين وكده ممكن تحصل فتنة داخلية تؤدي لعزل النجاشي\nلكن هو كان مُقدم العدل..هو ده كان القرار العادل بالنسبة له\n◇الثاني:\nقطع العلاقات مع مكة، لأن البلاد إللي بتؤذي المسلمين مينفعش الصالحون يعملوا معاها علاقات،\n فأمر النجاشي برد كل الهدايا إللي عمرو بن العاص جاء بها،\nوخرج هو وعبد الله بن أبي ربيعة من عنده مقبوحين مذلولين\n♡القرار الثالث :\nهو إن النجاشي ترك النصرانية وأسلم \nكل ده كان بسبب تحدي عمرو بن العاص\nعمرو مكر بالمسلمين عشان يُقتلوا...أهم قاعدين آمنين مكرمين\nومش بس كده ..أهه انطرد ورجعت له الهدايا وانقطعت العلاقات مع مكة \nلا وكمان النجاشي أسلم \nبجد يا عمرو مش عارفين كنا هنعمل إيه من غير تخطيطك ده \nوكما يُقال : انقلب السحر على الساحر\n\"وَيَمْكُرُونَ وَيَمْكُرُ اللَّهُ وَاللَّهُ خَيْرُ الْمَاكِرِينَ\"\nقل للعيون الحائرة   لله أيدٍ قاهرة\nالبطارقة معجبهمش إن النجاشي موافق المسلمين في كلامهم،\nإزاي يقول إنه عبد وهو عندهم إنه إله، فكانت هتحصل فتنة في أرض الحبشة وهم ميعرفوش أنه أسلم،\nفجمع النجاشي البطارقة وقال لهم إنتم زعلانين ليه وعاملين قلق\nفالبطارقة قالوا له : بسبب الكلام إللي قلته للمسلمين في عيسى\nفقال لهم : وإنتم بتقولوا إيه في عيسى\nفقال البطارقة: بنقول إنه إله\nفقال لهم النجاشي:\nوأنا على هذا.. ووضع يده على صدره، وكان تحت هدومه صحيفة مكتوب فيها لا إله إلا الله،\nفلما قال أنا على هذا ووضع يده عالصحيفة يقصد أنا على التوحيد، \nلكن البطارقة فهموا إنه يقصد بكلمة على هذا إنه موافق على كلامهم، فالبطارقة اطمأنوا ومبقاش في مشاكل،\nوظل النجاشي يكتم إسلامه طول حياته\n☆وهو ده كده مش كذب\n لا مش كذب ده اسمه تعريض يعني قال كلمة يقصد بها شيء وإللي قصاده فهم شيء تاني، \nوده طبعا غير الكذب\nالكذب إن الواحد يقول حاجة عكس الحقيقة، يعني يقول أنا فعلت كذا وهو لم يفعل، \nوالتعريض جائز وخصوصا لو في موقف زي بتاع النجاشي ده\n لكن الكذب محرم مفهوش كلام إلا في ثلاثة مواضع وهي:\nالإصلاح بين المتخاصمين وفي الحرب لتضليل العدو،\nوالكذب بين الزوجين في المشاعر،\nيعني لو رجل بيسأل زوجته إنتي بتحبيني ولا لأ وهي مش طايقة تبص في وشه يجوز إنها تقول له طبعا بحبك \nأمال تقول له مش طايقاك وتخرب على نفسها\nلأن البيوت بتقوم على الحب والرحمة بحيث لو اختفى الحب فالرحمة موجودة \n◇ممكن حد يسأل سؤال هنا ...هو النجاشي ليه مأعلنش إسلامه وواجه البطارقة والناس زي جعفر بن أبي طالب \nالنجاشي لم يعلن إسلامه لأنه خاف على حياته وملكه،\nوخدوا بالكم إن موقف النجاشي يختلف عن موقف جعفر بن أبي طالب\nيعني جعفر له وظيفة دعوية يجب عليه إنه يعلن الإسلام ويشرحه ويفصله ولو كان الثمن حياته،\nلأن كل كلمة هيقولها محسوبة على الإسلام فمينفعش تورية ولا تعريض ولا إخفاء معلومة ولا كذب ولا أي حاجة خالص في الموقف ده\nأما النجاشي فهو يعتبر زيه زي باقي المسلمين المُضطهدين في مكة فيجوز إنه يخفي إسلامه،\n مع إنه ملك بس موقفه ضعيف في مواجهة دولة كاملة على النصرانية بوزرائها برجال دينها،\nده غير إن الأصلح دلوقتي إنه يخفي إسلامه\nتخيلوا لو أعلن إسلامه ..مين هيدافع عن المسلمين وهم قلة\nهو هُيقتل والمسلمين هيقتلوا معاه ...يبقى استفدنا إيه دلوقتي \nلكن لما هو يخفي إسلامه ويمشي أمور الدولة،\nيبقى حافظ على حياته وملكه وحياة المسلمين وغيرهم من المستضعفين،\nفوظيفة جعفر كانت إعلان الدعوة بكل وضوح،\nووظيفة النجاشي إنه يحافظ على الدعوة دي من الهلاك\nوهنشوف إزاي المسلمين قعدوا في أرض الحبشة في حماية النجاشي خمسة عشرة سنة متصلة محدش اتعرض لهم بأذى\nهنسيب المسلمين في الحبشة في حماية النجاشي ونرجع مع عمرو بن العاص لمكة،\nعشان نشوف كفار قريش هيتصرفوا إزاي في الورطة إللي هم فيها دي \nتعذيب المسلمين فشل...المفاوضات مع رسول الله ﷺ فشلت،\nمحاولاتهم لاستعادة المسلمين الهاربين فشلت...جربوا كل حاجة مفيش ولا طريقة نافعة... ناقص إيه تاني\nأيوااااا مش فاضل غير☻ ......\nهنعرف إن شاء الله المرة الجاية إيه هي آخر وسيلة المشركين استخدموها للضغط على رسول الله ﷺ وعلى المسلمين \n☆"}, {"n": 54, "l": "الجزء 25 | شعب ابي طالب | وجزء 26 | موت ابي طالب", "u": "", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_الخامسة_والعشرون\n#شِعب_أبي_طالب\nوقفنا المرة إللي فاتت عند عمرو بن العاص لما رجع مكة بعد هزيمته أمام الوفد الإسلامي عند النجاشي،\nوصل عمرو بن العاص لمكة واجتمع مع سادات مكة وحكى لهم إللي حصل،\nإللي كان مراقب الأوضاع وتحركات سادات مكة هو أبو طالب بن عبد المطلب عم رسول الله ﷺ،\nهو عارف إنهم هم خلاص استنفذوا كل الطرق عشان يرجعوا المسلمين عن دينهم،\nمرت ثلاث سنوات من ساعة الجهر بالدعوة..ثلاث سنوات من التعذيب والقتل والمفاوضات والفرار بالدين للحبشة ومفيش فايدة،\nلا المسلمين عايزين يرجعوا عن إللي في دماغهم من اتباع دعوة الإسلام،\nولا المشركين سايبنهم في حالهم\nفخاف أبو طالب إن أحد من سفهاء قريش يتجرأ ويروح يقتل ابن أخيه\nوهو كان بيحبه جدا حتى أكثر من حبه لأولاده، \nفأبو طالب عمل زي اجتماع طاريء كده لبني عبد مناف إللي هم بني هاشم وبني المطلب،\nوالمطلب هو عم عبد المطلب إللي اتكلمنا عنه في البداية خالص،\nفاجتمع الفَرعين وطلب منهم حماية رسول الله ﷺ لأن أهل مكة مش هيسيبوه،\nفوافق الفَرعين على حماية رسول الله ﷺ والدفاع عنه، طبعا من غير أبو لهب، هو أخد جانب قريش،\nفانقسمت مكة قسمين، قسم يضم سادات قريش وأتباعهم والمؤيدين لهم ،\nوالقسم الثاني المسلمين بقيادة رسول الله ﷺ ومعاهم بني هاشم وبني المطلب مؤمنهم وكافرهم،\nفي نفس الوقت ده كانت قريش طلعت بفكرة جديدة لحرب دعوة الإسلام،\nقالوا بس، احنا نعمل قانون جديد ..قانون المقاطعة\nيعني يقاطعوا  المسلمين ويحاصروهم ويضيّقوا عليهم، \nكل أهل مكة لا يتزوجوا ولا يزوجوا أحد من بني عبد مناف مؤمنهم وكافرهم،\nلا يبيعوا ولا يشتروا منهم، ولا حتى يقعدوا معاهم ولا يكلموهم،\nومفيش مانع إن لو واحد من أهل مكة شك إن جاره من بني عبد مناف أو حتى متعاطف معاهم إنه يبلّغ عنه،\nأيوة يا جماعة تعاونوا معانا خلوا مكة تنضف من الناس إللي عايزة تخرِب البلد دي \nومش هيبقى في أي مصالحة بين أهل مكة وبني عبد مناف إلا لما ينفّذوا كل إللي أهل مكة يقولوا عليه \nوراحوا كاتبين الكلام ده في صحيفة زي ورقة بالمفهوم بتاعنا يعني، وعلقوها داخل الكعبة،\nعشان تبقى زي حاجة شرعية كده ميرجعوش فيها مهما حصل \nومع إن القانون الجديد ده مُخالف للعُرف وكل القوانين بتاعة مكة، بس عادي يعني يا جماعة الورق ورقنا والدفاتر دفاترنا \nمش مهم العُرف ولا المروءة ولا مراعاة إننا بيننا عشرة سنين طويلة، ولا إننا في الشهر الحرام ولا في البلد الحرام، أهم حاجة المصالح، هي دي إللي تهمنا دلوقتي\nوبدأ التنفيذ فورا من أول ليلة في شهر الله المحرم من السنة السابعة من البعثة،\nاجتمع المسلمون ومعاهم بني عبد مناف في مكان في مكة وقعدوا كلهم فيه واتسمى المكان ده《شِعْب أبي طالب》\nعايزاكم تتخيلوا بداية معاناة جديدة ...\nالرجال والنساء والأطفال وكبار السن المؤمن والكافر مع بعض في نفس المكان مُحاصرين مضطهدين،\nإعلام سادات مكة عمال يُشوّه في صورتهم أمام الناس،\nلو حاولوا يشتروا ولا يبيعوا محدش بيتعامل معاهم، ولو اشتكوا يقولوا لهم تستاهلوا إللي يجرى لكم،\nمش إنتم اتبعتم محمد، روحوا لمحمد خليه ينفعكم\nمنعوا عنهم الأكل، وحتى لو جت قوافل من برة مكة فيها أكل كان كفار قريش يشتروها من التجار بسعر عالي،\nعشان محدش من المسلمين ولا بني عبد مناف يقدر يشتري\nده غير الإهانات طبعا والأذى، وأي حد يفكر بس كده إنه يتعاطف معاهم هنعمل فيه زيهم\nالوضع ده مستمرش يوم ولا اتنين ولا شهر ولا شهرين ...ده استمر ثلاث سنوات، ستة وثلاثون شهر،\nتخيلوا إن أصوات صراخ  النساء والأطفال من الجوع كانت تُسمع من خارج الشّعب،\nووصل بهم الجوع إنهم أكلوا ورق الشجر\nموقف حصل مع سعد بن أبي وقاص بيحكي إنه كان في شعب أبي طالب مع المسلمين بيقول مرة قام بالليل لقضاء حاجته، \nفوهو بيتبول سمع صوت قعقعة تحت البول، فلقاها قطعة  يابسة من جلد جمل،\nفأخذها وغسلها وأحرقها وطحنها وسفها بالمية \nبيقول سعد إن الأكلة دي قوته ثلاث ليال\nوده بيحصل للمسلمين وأهل مكة منعّمين مرفّهين آمنين في بيوتهم \nأهل الإيمان في ابتلاء وفقر وجوع وخوف، وأهل الباطل في نعيم آمنين في بيوتهم\n☆في ناس من زماننا دلوقتي ممكن يقولوا هو أنا ليه أصبر عالهم ده، أو يارب أنا بطيعك وبعبدك وإنت تعمل معايا كده؟\nهو مش المفروض تكافئني على الطاعة إللي بعملها،\nلالا أنا مش مستحمل ...وفعلا الواحد يسيب طريق ربنا للأسف\nعارفين،\nأهه الإبتلاءات دي معمولة عشان الناس دي..الناس إللي إيمانها مش راسخ، \nإللي لما تبقى الدنيا ماشية معاها حلو يبقى ربنا جميل والدين ده حاجة حلوة أوي\nلكن مع أول ابتلاء صغير تلاقيها وقفت واعترضت، وممكن الإبتلاء يبقى أشد عشان ربنا يورّيها نفسها وإن هي إللي سابت الطريق بنفسها\n\"وَمِنَ النَّاسِ مَن يَعْبُدُ اللَّهَ عَلَىٰ حَرْفٍ فَإِنْ أَصَابَهُ خَيْرٌ اطْمَأَنَّ بِهِ ، وَإِنْ أَصَابَتْهُ فِتْنَةٌ انقَلَبَ عَلَىٰ وَجْهِهِ خَسِرَ الدُّنْيَا وَالْآخِرَةَ\"\nالدين بقى مش هيُنصر بالناس المُزَعزة دي\nعشان كده ييجي الإبتلاء عشان ينظف الصف المسلم من الناس دي\nفاكريييين قصة طالوت وجالوت\nوالمراحل إللي مرّوا بها الأول والإبتلاءات قبل ما يواجهوا الجبارين وينتصروا عليهم،\nأهه دي من سنن الله الكونية\nابتلى جيش طالوت وبيبتلي المسلمين مع رسول الله ﷺ عشان إللي هيثبت في الإبتلاءات الشديدة المُزلزلة دي،\nهو إللي هيقدر ينصر رسالة الإسلام ويقيم الدولة،\nغير كده مفيش\nهتلاقي ربنا بيبتلي الناس عشان يطلع المستخبي، كم مرة شفنا إنسان ظاهره التقوى والصلاح وإن متطلعش منه العيبة أبدا، \nوفجأة مع ابتلاء أو اختبار اتحط فيه بقى شخصية تانية خالص عمرنا ماكنا نتوقعها؟\nماهو ربنا قال : \"وَنَبْلُوَ أَخْبَارَكُمْ \"\nالمستخبي كله هيبان وهيطلع بمزاجنا أو مش بمزاجنا،\nمن كانت له سَريرة صالحة أو سيئة أظهر الله عليه منها رداء يُعرف به\nاستمر العذاب والمعاناة على المسلمين وعلى المشركين ثلاث سنوات، \nوخلال الثلاث سنوات كان بينزل القرآن يثبت قلوب المؤمنين،\nفي السنة السابعة للبعثة أول سنوات الحصار نزلت سورة السجدة، \nهقول لكم منها كم آية عشان تستشعروا المسلمين ساعتها كان إيه شعورهم:\n\"وَلَوْ تَرَى إِذِ الْمُجْرِمُونَ نَاكِسُوا رُءُوسِهِمْ عِنْدَ رَبِّهِمْ رَبَّنَا أَبْصَرْنَا وَسَمِعْنَا فَارْجِعْنَا نَعْمَلْ صَالِحًا إِنَّا مُوقِنُونَ \"\n\"أَفَمَنْ كَانَ مُؤْمِنًا كَمَنْ كَانَ فَاسِقًا لَا يَسْتَوُونَ \"\n\"وَجَعَلْنَا مِنْهُمْ أَئِمَّةً يَهْدُونَ بِأَمْرِنَا لَمَّا صَبَرُوا وَكَانُوا بِآيَاتِنَا يُوقِنُونَ\"\nتخيلوا لما المسلمين كانوا بيسمعوا الآيات دي كانوا بيحسوا بإيه، وإزاي الآيات كانت بتهدّي من نفوسهم\nلكن الواحد ممكن يستغرب \nطيب المسلمين بيؤمنوا بيوم القيامة وإن جزاءهم بعد الصبر هو الجنة، \nالمشركين بقى إيه إللي مصبرهم عالعذاب ده \nهم كان عندهم حَمِية...غِيرة...نخوة إزاي واحد من قبيلته يتعمل فيه كده، \nوالعهد إللي أخذوه على أنفسهم عشان يحموا رسول الله ﷺ،\nضحوا بأموالهم وزوجاتهم وأبنائهم عشان يوفّوا بعهدهم، وكانوا فعلا أد كلمتهم، مش مجرد خطب وأشعار وكلمات وخلاص\nوالنخوة والوفاء بالعهد كانت من أهم مميزات العرب في الجاهلية إللي أهلتهم لنزول رسالة الإسلام فيهم\n☆تخيلوا لو الموقف ده حصل في عصرنا رد فعل فعل الناس هيبقى إيه\nبصوا هو للأسف مش لو\nلأنه بالفعل واقع في عصرنا في كذا بلد من بلاد المسلمين، والدنيا ماشية عادي\nفي السنة الثامنة نزلت سورة هود..وما أدراكم ما سورة هود\nفيها قصة عاد وثمود ونوح ولوط وغيرهم من الأنبياء وجزاء الذين سُعدوا والذين شَقوا وأهوال يوم القيامة\nوارجعوا لقصص الأنبياء وتخيلوا رسول الله ﷺ وهو بيقرأ وبيشرح الآيات للصحابة \nشوفوا ربنا ختم السورة بإيه:\nأول رسالة لرسول الله ﷺ وللمؤمنين معاه ولنا احنا كمان ركزوا\n\"وكُلاًّ نَّقُصُّ عَلَيْكَ مِنْ أَنبَاء الرُّسُلِ مَا نُثَبِّتُ بِهِ فُؤَادَكَ وَجَاءَكَ فِي هَذِهِ الْحَقُّ وَمَوْعِظَةٌ وَذِكْرَى لِلْمُؤْمِنِينَ\"\nالرسالة التانية للكفار والظلمة \n\"وقُل لِّلَّذِينَ لاَ يُؤْمِنُونَ اعْمَلُواْ عَلَى مَكَانَتِكُمْ إِنَّا عَامِلُونَ\nوَانتَظِرُوا إِنَّا مُنتَظِرُونَ\"\nبعد ما ربنا ثبت رسوله والمؤمنين وقال للكفار اعملوا إللي إنتم عايزينه من باب التهديد لهم، ختم السورة:\n\"ولِلَّهِ غَيْبُ السَّمَاوَاتِ وَالأَرْضِ وَإِلَيْهِ يُرْجَعُ الأَمْرُ كُلُّهُ فَاعْبُدْهُ وَتَوَكَّلْ عَلَيْهِ وَمَا رَبُّكَ بِغَافِلٍ عَمَّا تَعْمَلُونَ\"\nوصلنا للسنة التاسعة للبعثة ونزلت سورة سبأ...أنا مش عارف أحط لكم أنهي آية...السورة محتاجة تتحط كلها، آيات مُعجزة فعلا\nارجعوا اقرأوها كده وانتم مستحضرين موقف رسول الله ﷺ والصحابة معاه وانتم هتحسوا بمعنى الآيات\nطال الحصار على المسلمين ومش واضح أي ملامح للفرج\nكان في ناس متضايقين من إللي بيحصل لبني عبد مناف كانوا بيقولوا إزاي يعني احنا ناكل ونشرب والناس دي لأ،\nإزاي عيالنا يناموا شبعانين وأطفال بني عبد مناف يناموا جعانين واحنا سامعين أصوات بكائهم من الجوع\nفكانوا بيرسلوا لشعب أبي طالب بعض الطعام سرا،\nزي حكيم بن حزام إللي كان بيرسل لعمته خديجة بنت خويلد زوجة رسول الله ﷺ،\nوزي واحد اسمه 《هشام بن عمرو》 من بني عامر،\n لكن الأكل مكنش كافي وكمان لازم يكون في حل جذري للموضوع ده\nفبدأ يفكر هشام بن عمرو يعمل إيه\nقال لازم ننقض الصحيفة الظالمة دي \nلكن هو لوحده مش هيقدر يعمل حاجة، فبدأ يدوّر على رجل قوي له كلمة مسموعة في قريش؛\nلأن زعيم المعارضة أبو جهل أكثر المتحمسين للمقاطعة له مكانة كبيرة في قريش لأنه هو زعيم أكبر قبيلة كانت بتنازع بني هاشم وتتنافس معاها،\nفدي فرصة مناسبة جدا عشان قبيلة أبي جهل بني مخزوم يحققوا انتصار على بني هاشم\nفهشام بن عمرو محتاج واحد له مكانة زي أبي جهل من قبيلة بني مخزوم القبيلة القوية دي،\nفراح لواحد اسمه 《زُهير بن أبي أمية》 وراح للشخص ده بالذات لأن أمه تبقى عاتكة بنت عبد المطلب عمة رسول الله ﷺ،\nفهشام بن عمرو هيستغل العصبية الفطرية إللي عنده\nفقال له:\nيا زهير! هو إنت عادي كده تاكل وتشرب وأخوالك بيحصل فيهم إللي إنت عارفه، وماشي ورا أبي جهل\nوبعدين قال له كلمة خطيرة \nقال:\nأحلف لك بالله إن لو كانوا دول أخوال أبي جهل وإنت إللي روحت قلت له تعال نقاطع الناس دي مكنش هيوافق\nفزهير اتحمس وقال: طيب انا هعمل إيه وأنا رجل لوحدي، لو كان معايا حد تاني كنت قمت ونقضت الصحيفة دي\nفقال له هشام : انا لقيتهولك\nفقال له زهير مين:\nفقال هشام: أنا \nفقال زهير: طيب شوف لنا واحد ثالث\nفهشام ترك زهير وراح لواحد ثاني من أصحاب الأخلاق والمروءة اسمه المُطعِم بن عَدي،\nوقعد يذكره بأرحام بني المطلب وبني هاشم فقال له المطعم:\nوأنا هعمل إيه وانا رجل لوحدي\nفقال له هشام:\nلقيت لك واحد، فقال المطعم: مين\nفقال له : أنا \nقال المطعم: شوف لنا ثالث، قال هشام في واحد فعلا هو \nزهير بن أبي أمية، فقال له المطعم: طيب شوف لنا رجل رابع\nالمطعم كان من قبيلة ثالثة، يبقى كده عندنا ثلاثة أشخاص من ثلاثة قبائل مختلفة،\nالمهمة صعبة ويمكن مستحيلة\nالناس دي هتقف قصاد قريش كلها في حاجة كانوا اتفقوا عليها،\nومع ذلك هشام بن عمرو 《الكافر》 لم يستسلم\nوراح فعلا يدور على رجل رابع،\n فراح لأبي البختري بن هشام، \nوقال له زي ما قال للمطعم بن عدي، فسأله أبو البختري:\nهل في حد معانا على الموضوع ده\nفقال له هشام : أيوة ، أنا والمطعم بن عدي وزهير بن أبي أمية\nفقال له أبو البختري: طيب شوف لنا رجل خامس\nفسبحان الله خرج هشام بن عمرو بكل حماس يدور على رجل خامس\n☆أظن لو حد مننا مكانه كان زماننا يئسنا من الرجل الثاني\nفراح لواحد اسمه زَمعة بن الأسود وحكى له القصة وقال له إن في أربعة مجتمعين على الموضوع ده فقال له إنه موافق\n☆الحمد لله مقلوش شوف لنا واحد سادس \nالمهم الخمسة اجتمعوا وأخذوا القرار الجريء إللي هيعارضوا به كل سادات قريش، \nورأيهم ده ممكن يؤدي لانقسام شديد في مكة، متخيلين هينصروا دين هم مش مقتنعين به أساسا \nفإيه إللي يجبرهم أصلا على كده وهم مش هيستفيدوا أي حاجة أصلا\nكل إللي حركهم كانت الحمية والنخوة\nطبعا كله بتقدير ربنا، لأن ربنا إذا أراد شيئا هيأ أسبابه\nاجتمعوا واتفقوا هيعملوا إيه واتفقوا على اليوم،\nوقال لهم زهير إنه هو إللي هيبدأ الكلام وإنتم ادخلوا ورايا على طول\nراح الخمسة في اليوم الموعود ، طبعا كل واحد لوحده عشان محدش ياخد باله\nدخلوا المسجد وقام زهير ونادى على أهل مكة وقال : \nيا أهل مكة!\nبقى احنا نأكل ونشرب ونلبس وبنو هاشم هَلْكى محدش يبيع لهم حاجة ولا يشتري منهم\nوالله ما أنا قاعد غير لما نقطع الصحيفة الظالمة دي \nّسمع الكلام أبو جهل اتعصب...إيه الراجل إللي هيضيع عليّ فرصتي دي\nفراح قايم بكل حماسة وقال:\nكذبت والله ما نقطعها\nراح قايم زَمعة بن الأسود \n وقال لأبي جهل:\nأنت والله أكذب\nإحنا أصلا مكناش موافقين عليها لما اتكتبت من الأول \nفراح قايم أبو البختري بن هشام وقال:\nصدق زمعة احنا مش راضيين عن إللي اتكتب فيها \nفقام المطعم بن عدي وقال:\nصدقتما، وأي حد يقول غير كده يبقى كاذب واحنا نتبرأ ألى الله منها\nوبعدين قام هشام بن عمرو إللي جمعهم أصلا وقال نفس كلامهم وأصر على نقض الصحيفة هو كمان\nإللي يشوف الموقف... يلاقي إن خمسة من سادات قريش عايزين ينقضوا الصحيفة وأبو جهل الوحيد إللي واقف بيدافع،\nوالباقيين قاعدين ساكتين بيتفرجوا، والأغلبية الصامتة ملهاش أي لازمة \nوسط ماهم بيتخانقوا كده لقوا إللي داخل عليهم \nمين إللي دخل ...وعايز إيه؟\nوهل الحصار اتفك ولّا لأ...ده إللي هنعرفه الجزء الجاي إن شاء الله\n#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_السادسة_والعشرون\n#موت_أبي_طالب\nكنا واقفين المرة إللي فاتت عند أبو جهل لما كان واقف بيدافع عن نقض الصحيفة،\nوقصاده خمسة مُنظّمين من سادات مكة عايزين ينقضوا الصحيفة،\nوهم واقفين كلهم بيتخانقوا كده ...فجأة لقوا أبو طالب بن عبد المطلب عم رسول الله ﷺ داخل عليهم المسجد\nفشاف أبو طالب الناس واقفة وبتتكلم فدخل في الكلام وقال لهم:\nابن أخويا بيقول إن الصحيفة إللي إنتم معلقينها في الكعبة وفيها قانون المقاطعة أكلتها دودة الأرض ومسبتش فيها حاجة غير اسم الله عز وجل...باسمك اللهم\nكفار مكة استغربوا إيه إللي بتقوله ده\nفقال لهم: روحوا هاتوا الصحيفة لو لقتوها زي ما ابن أخي قال...ترجعوا عن المقاطعة،\nولو كان كاذب هنتركه لكم وإنتم خذوه واقتلوه\nفقالوا : صح معاك حق ..ده العدل\nفراح زعماء مكة ودخلوا الكعبة وبيشوفوا الصحيفة لقوها زي ما رسول الله ﷺ قال\nمعجزة واضحة أهه قصادهم، طبعا مكنش في حل تاني غير إنهم ينهوا المقاطعة زي ما وعدوا أبا طالب،\nوانتهى حصار المسلمين بعد ثلاث سنوات في محرم من السنة العاشرة من البعثة،\n☆شوفوا،\n هو ربنا كان قادر إنه ينهي الموضوع كله في لحظة،\nلكن ربنا أراد إنه يعلم الصحابة ويعلم كل الأجيال إللي هتيجي بعدهم: الصبر والثبات على الإيمان،\nوكمان بيعلمنا إن أصعب المشاكل إللي ممكن يكون الإنسان فيها ممكن تتحل من طريق عمره ما يخطر على بال أحد أصلا،\nوبيحله كمان من أصعب الأبواب تخيلوا \nالطبيعي إن إللي يسعى في نقض الصحيفة مين؟\nبنو هاشم والمسلمون صح...لأنهم أكثر ناس متضررين،\nربنا قال للجميع لأ...إللي هيسعى في حل الموضوع رجل كافر ملوش علاقة أصلا بأي حاجة \nومش بس كده ..خذوا الأصعب، إللي هينهي القصة دي كلها..دودة\nمتخيلين...ربنا سخر دودة عشان تنهي حصار صعب شديد استمر ثلاث سنوات على المسلمين\nالدودة قعدت ثلاث سنوات تأكل في الصحيفة، حد كان يخطر على باله إللي حصل ده أصلا\nفاتعلموا الصبر واتعلموا كويس قوي كلام ربنا:\n\"وَمَا يَعْلَمُ جُنُودَ رَبِّكَ إِلَّا هُوَ\" \nكل حاجة هتتحل بس اصبروا وإنتم هتشوفوا العجب \nانتهى الحصار وخرج المسلمون أشد ثباتا على الإسلام وأقوى يقينا في الله\nفي بدايات السنة العاشرة من البعثة مرض أبو طالب عم رسول الله ﷺ،\nكان وصل عمره لثمانين سنة، وكمان خرج من حصار ثلاث سنوات أكل فيها ورق الشجر ،\nده غير القلق إللي كان عايش فيه بسبب خوفه على رسول الله ﷺ،\nفكل ده أثّر على صحته وأصبح مريض نايم في السرير مش بيتحرك،\nالناس كلها عرفت بمرض أبي طالب وتوقعوا إنه يموت قريب\n فخاف زعماء مكة\nهم مش ناويين يسيبوا رسول الله ﷺ، هيؤذوه يعني هيؤذوه\nلكن المشكلة إنهم لو آذوه بعد موت أبي طالب، العرب هتعايرهم...إنتم استغليتم موت عمه عشان تستفردوا بيه وتعملوا إللي إنتم عايزينه\nوهم كانوا بيراعوا أوي إن محدش يعيّرهم، كانت حاجة كبيرة عندهم \nعملوا إيه\nراح وفد من خمسة وعشرين رجل من سادات مكة لأبي طالب ،منهم أبو جهل، وأبو سفيان وأمية بن خلف، وعتبة بن ربيعة وغيرهم،\nاجتمعوا عنده وقالوا له:\nيا أبا طالب!\nإنت عارف مكانتك عندنا عاملة إزاي، وإنت شايف حالتك إيه دلوقتي، واحنا خايفين عليك من الموت وإنت عارف إللي بيننا وبين ابن أخوك\nفانت ابعث حد يجيبه ونشوف حل وسط بيننا، احنا هنسيبه في حاله وهو يسيبنا في حالنا،\nونعيش في سلام مع بعض من غير أي مشاكل ، أظن مفيش أحسن من كده\n☆يعني عايزين رسول الله ﷺ يشوف الكفار يعبدوا الأصنام وميتكلمش ولا يدعوهم،\nعايزين رسول الله ﷺ يتقبل الناس على كفرهم وصباح الخير يا جاري وانت في حالك وأنا في حالي \nعايزين رسول الله ﷺ يشوف الفواحش والظلم والربا وكل أمور الجاهلية ويسكت عادي،\nمش إنت بتعبد إلهك وأنا بعبد إلهي، خلاص بقى مشيها،\nسيبك من الأمر بالمعروف والنهي عن المنكر والكلام ده، كل واحد حر\n \nأظن العرض ده يعتبر مُغري جدا لرسول الله ﷺ والمؤمنين \nأهل مكة بعد ما كانوا رافضين الإسلام تماما وبيعذّبوا المسلمين عشان يتركوا دينهم، \nقدموا تنازلات أخيرا وتقبلوا فكرة وجود الإسلام، وكمان المسلمين لسه خارجين من حصار كان تاعبهم جدا،\nفهمّ خلاص مش هيقدروا يستحملوا أي حاجة دلوقتي خالص\nوأبو طالب إللي كان بيحمي رسول الله ﷺ هيموت، فدي تعتبر فرصة مثالية للمسلمين مش هتتعوض\nوأرسل أبو طالب لرسول الله ﷺ فلما جاء قال أبو طالب لرسول الله ﷺ في حضور وفد المشركين:\nدول أشراف قومك اجتمعوا على إنهم يعطوك ويأخذوا منك،\nيعني هتعيشوا مع بعض في سلام من غير أي مشاكل\nفرد عليه رسول الله ﷺ وقال:\nياعم! إيه رأيك أدعوهم لحاجة أحسن من كده؟\nفقال أبو طالب: هتدعوهم لإيه\nقال رسول الله ﷺ:\nأدعوهم إنهم يقولوا كلمة واحدة يملكوا بها العرب والعجم!!\nأصلا أهل مكة مكنوش يحلموا بوحدة العرب،\nدلوقتي بتكلمنا إننا نكون حكام للعرب والعجم...فارس والروم\nفأبو جهل بكل حماسة قال:\nقول إيه هي الكلمة دي...واحنا هنقولها لك وكمان هنقول لك عشر أمثالها \nفقال رسول الله ﷺ:\n تقولون لا إله إلا الله وتتركوا ما تعبدون من دونه!!\nفاتصدموا كلهم طبعا...هو إنت لسه في القصة دي\nورفض كفار مكة عرض رسول الله ﷺ ورفض رسول الله ﷺ عرض كفار مكة، وفشلت المفاوضات\n☆عارفين لو كنا بنحكي عن حد تاني هو إللي عمل كده غير رسول الله ﷺ ،كان زمان الناس قعدت تقول: \nمش يحمد ربنا على النعمة إللي هو فيها\nماهم قالوا لك اعبد ربنا عادي أهه\nخلاص خليك في حالك وهم في حالهم وبعدين في المستقبل يبقى يحلها ربنا،\nإيه التفكير ده...مش تكسب أرض وتعيش في أمان، ويمكن في المستقبل ربنا يهديهم،\nثم إنت أصلا محلتكش حاجة وكل الناس ضدك..يبقى تبوس إيدك وش وظهر وترضى باللي هم عرضوه عليك، إنت هنتهب ولا إنت شايف نفسك على إيه\nبس للأسف الناس مش فاهمة إن أمور الدين العقيدة مفيهاش فصال\nرسول الله ﷺ رفض إنه يتنازل عن أي حاجة ولو بسيطة في الدين مقابل أمنه وسلامته وسلامة المسلمين،\nومحدش من المسلمين اعترض أبداااا على قرار رسول الله ﷺ ، لأنهم واثقين إنه لا ينطق عن الهوى،\nوكمان واثقين في قوة دينه وإنه دائما وأبدا هيقدم مصلحة الدين والدعوة على أي مصلحة تانية\nعشان كده القائد إللي يقود أمة الإسلام لازم يمشي على نفس منهج رسول الله ﷺ وتكون مصلحة الدين عنده رقم واحد\nلو قدم أي مصلحة تانية على مصلحة الدين هتكون نهايته الفشل\nاشتد المرض بأبي طالب المساعد الأكبر للمسلمين والمدافع الأول عن رسول الله ﷺ ودعوته على الرغم من كفره،\nعرف رسول الله ﷺ إن عمه أبو طالب مريض جدا فراح له  ولقاه بيحتضر\nوكان عنده أبو جهل، اللحظة الحاسمة جت، مفيش أي مجال،\nللتردد، رسول الله ﷺ بقاله عشر سنين بيدعوه للإسلام لكن مفيش فايدة،\nدي آخر فرصة...لو مات على الكفر انتهى...هيكون خالد مخلد في النار، مش هيطلع منها أبدا \nبعد كل الدفاع وتحمل الألم ده كله يُخلد في النار \nوقف رسول الله ﷺ على رأسه وقعد يقول لعمه:\nيا عم قل لا إله إلا الله... كلمة أقف أدافع بها عنك يوم القيامة  قصاد ربنا!!\n☆تخيلوا قلب رسول الله ﷺ كان عامل إزاي وهو بيقول الكلام ده لعمه إللي رباه وكان بيحبه ويفضّله على أولاده،\nعمه إللي محدش وقف جنبه أده\nمجرد إن الواحد يضع نفسه مكان رسول الله ﷺ مع أحد بيحبه بيحس إن قلبه هينخلع،\nفما بالك برسول الله ﷺ إللي كان أرق الناس قلوبا، وكان أحرص الخلق على هداية الناس\nالموقف مؤلم فعلا\nرسول الله ﷺ عمّال يحاول مع عمه في موقف مؤثر جدا\nوفجأة واحد يقول:\nيا أبا طالب! إنت هتسيب ملة عبد المطلب \nإزاي تسيب دين آباءك وأجدادك \nأبو طالب كان حيران بين ابن أخوه إللي بيحبه ونفسه ميكسرش بقبله،\nوبين كلام أبو جهل إللي يعتبر منطقي بالنسبة له\nفي الآخر قال:\nلولا إن قريش تعيرني ويقولوا إنه قالها بسبب خوفه من الموت لكنت قلتها عشان خاطرك إنت بس، وقال إنه على ملة عبد المطلب...ومات\nمات على ملة عبادة الأصنام\nتخيلوا شدة ألم رسول الله ﷺ في اللحظة دي،\nتخيلوا الذكريات إللي مرت عليه في اللحظة دي من صغره لحد النهاية،\nوفعلا دي النهاية...مفيش بينهم لقاء مرة تانية،\nأبو طالب خالد مُخلد في النار ورسول الله ﷺ في الدرجات العُلَى من الجنة،\nألم رسول الله ﷺ كان شديد جدا مش عشان عمه مات، لكن عشان هو مات على الكفر،\nلما بنفقد حد عزيز علينا بنمني نفسنا إننا نلتقي في الجنة ،\nلكن رسول الله ﷺ مش هيلتقي لا بأمه ولا أبوه ولا عمه في الجنة\nأشد الناس بلاءا الأنبياء\nفقال رسول الله ﷺ بعد موت أبي طالب في حزن شديد:\nوالله لأستغفر لك الله مادام ربنا لم ينهانِ عن كده!\nونزل قول الله :\n\"إِنَّكَ لَا تَهْدِي مَنْ أَحْبَبْتَ وَلَٰكِنَّ اللَّهَ يَهْدِي مَن يَشَاءُ\"\n ونزل:\n\"مَا كَانَ لِلنَّبِيِّ وَالَّذِينَ آمَنُوا أَن يَسْتَغْفِرُوا لِلْمُشْرِكِينَ وَلَوْ كَانُوا أُولِي قُرْبَىٰ مِن بَعْدِ مَا تَبَيَّنَ لَهُمْ أَنَّهُمْ أَصْحَابُ الْجَحِيمِ\"\n☆محتاجين نقف هنا كذا وقفة،\n◇أولا:\n نحمد الله على نعمة الإسلام وندعوه أنه لا يحرمنا منها نحن ومن نحب يارب آمين\n◇ثانيا: \nشفنا أثر الصحبة السيئة على الإنسان، صديق السوء أبو جهل استمر يذكّر أبا طالب بالكفر ويذكره بالعادات والتقاليد والناس لحد ما دي كانت نهايته\nفاللي عنده صاحب دايما بيعايره بالتزامه أو بيذكره بالمعاصي أو بيساعده على المعصية،\nيبعد عنه فورا\nكما يُقال: انْجُ سعد قد هلك سعيد،\nيعني تخيلوا سعيد هلك فما بالكم بسعد إيه إللي هيحصله\nيعني لو واحد بيغرق هينقذ نفسه الأول ولّا وهو بيغرق هيروح ينقذ صاحبه ويغرقوا هم الإثنين مع بعض\nكذلك إللي بيكون عايز يقرب من ربنا أول حاجة لازم يعملها إنه يبعد عن أي حد بيجره للمعصية،\nمحدش هينفعنا يوم القيامة ، كله هيهرب من الثاني،\nأبو جهل مش هينفع أبو طالب بحاجة يوم القيامة\n\"الْأَخِلَّاءُ يَوْمَئِذٍ بَعْضُهُمْ لِبَعْضٍ عَدُوٌّ إِلَّا الْمُتَّقِينَ\"\n◇ثالثا : \nسؤال ممكن ييجي في دماغنا، ليه أبو جهل كان مصمم إن أبو طالب ميدخلش الإسلام، مع إنه خلاص هيموت ، فكان يسيبه \nأبو جهل كان خايف إن لو أسلم أبو طالب كل بني هاشم يسلموا بسببه،\nولو حصل كده ، احتمال كبير مكة تُؤمن، وكده سلطته في مكة هتضيع،  \nفهو أهم حاجة عنده طبعا مصلحته حتى لو على حساب مصلحة غيره،\nودي بنشوفها في حياتنا كثير جدا للأسف\n◇رابعا:\nالكفر لا تنفع معه طاعة...مهما كان الإنسان حَسن الخُلق مُدافع عن حقوق المظلومين،\nحتى لو دافع عن دين الإسلام ومات وهو غير مسلم ، فهو في النار، لن تنفعه أي طاعة مادام لا يشهد أن لا إله إلا الله أولا ومحمد رسول الله ثانيا\nلكن ربنا لا يظلم أحد، كان أبو طالب أشد الناس دفاع عن رسول الله وعن الدعوة،\nفرسول الله ﷺ هيشفع في أبي طالب يوم القيامة إنه ميكونش في الدرك الأسف من النار،\nهيكون عذابه إنه ييقى في قدمه جمرتين أو نعلين زي جزمتين من نار يغلي منهما دماغه، وده أهون عذاب لأهل النار ربنا يعافينا\n◇خامسا:\nسؤال مهم ومحير جدا...ليه رسول الله ﷺ مع إنه مستجاب الدعوة ودعا لأكثر من شخص بالهداية وربنا هدهم،\nمدعاش لأبي طالب إن ربنا يهديه \n¤قبل الإجابة لازم نفهم الأول إن رسول الله ﷺ قعد عشر سنين يدعو عمه للإسلام واجتهد في ذلك، \nحتى إن اثنين من أبناء أبي طالب وزوجته أسلموا، ومع ذلك هو لم يؤمن،\nيعني رسول الله ﷺ عمل إللي عليه من الأسباب الدنيوية،\n زي ما نوح عليه السلام عمل مع ابنه وزي ما إبراهيم عليه السلام ما عمل مع أبوه\n¤ربنا قال لرسوله:\n\"إِنَّكَ لَا تَهْدِي مَنْ أَحْبَبْتَ وَلَٰكِنَّ اللَّهَ يَهْدِي مَن يَشَاءُ ۚ وَهُوَ أَعْلَمُ بِالْمُهْتَدِينَ\"\nيعني مش عشان أنا بحب الشخص ده فخلاص هخليه يهتدي، \nممكن أكون بحبه لكن نهايته إنه من أهل النار\nفدي أول قاعدة بنتعلمها إن ربنا يهدي من يستحق الهداية فقط،\nبيرى قلوب العباد هل الشخص ده يستحق الهداية ولّا لأ،\nوأبو طالب كان عايز يدخل في الإسلام إرضاءا لرسول الله ﷺ فقط، يعني عشان ميزعلش ، \nمش لأنه مؤمن بالله وبرسالة الإسلام، فالمحرك الرئيسي لكل أفعال أبو طالب هو حبه لابن أخوه كابن أخ مش كرسول من عند الله\n¤مش كل دعاء رسول الله ﷺ يُستجاب، والدليل على كده في صحيح مسلم إن رسول الله ﷺ طلب من ربنا إنه يُعطي أمته ثلاثة أمور، فأعطى له اثنتين ومنع عنه واحدة،\nلحكمة ربنا يعلمها\nده غير كده رسول الله ﷺ لو دعا بحاجة وهي تخالف ماقدّره الله ربنا بيمنعه من الاستمرار في الدعاء ده،\nفكان بيدعو لناس معينة وبيدعو على ناس ثانية،\nفربنا أنزل:\n\"لَيْسَ لَكَ مِنَ الْأَمْرِ شَيْءٌ أَوْ يَتُوبَ عَلَيْهِمْ أَوْ يُعَذِّبَهُمْ فَإِنَّهُمْ ظَالِمُونَ \"\nفمبقاش يدعي، فربنا هو إللي بيوفق ويُلهم رسول الله ﷺ الدعاء الموافق قدر الله\nفتكون نتيجة الكلام ده كله:\nإن أبا طالب لا يستحق الهداية وبالتالي ربنا لم يُلهم رسول الله ﷺ إنه يدعو لعمه أبي طالب لأن قدر ربنا في أبي طالب إنه هيموت على الكفر،\nوحتى《 لو 》رسول الله ﷺ دعا له بالهداية، فإما ربنا هيقول له إنه لا يدعو بشيء ربنا هو الحكم فيه،\nأو إن ربنا مكنش هيستجيب لرسوله لحكمة يعلمها سبحانه،\nو كان من الحكمة إن أبو طالب لم يسلم: إن الكفار مقدروش يتعدوا على رسول الله ﷺ، \nأو خلونا نقول إن أبا طالب خفف عنه أذى المشركين، ومكنش بيتجرأ عليه غير السادة،\nلكن لو كان أسلم أبو طالب كان هيبقى زيه زي باقي المسلمين وهيحصل الأذى الشديد للجميع\n◇سادسا: \nمينفعش ندعي بالرحمة ولا نستغفر لأي أحد شفناه مات على الكفر،\nوكمان مينفعش نحبه المحبة الدينية،\nيعني مينفعش نحبه لأنه مجتهد في دينه مثلا ، ولا إنه متمسك بدينه، أو بسبب محبتنا له نعصي الله\nلكن المحبة الطبيعية الفطرية عادي، زي ما رسول الله ﷺ كان بيحب عمه كده،\nوزي ما إبراهيم عليه السلام كان بيحب أبوه، وزي ما نوح عليه السلام كان بيحب ابنه،\nكل دي محبة فطرية طبيعية، ومفيش تعارض بين إن الإنسان يحب أمه أو أبوه أو عمه محبة فطرية، \nوفي نفس الوقت يكره الكفر إللي هم عليه ويحاول إنه يغيره\nزي ما رسول الله ﷺ حاول مع عمه وباقي الأنبياء إللي قلناهم.\nمات أبو طالب في السنة العاشرة من البعثة، وعلى الرغم من إن المدافع الأول عن الدعوة مات، \nإلا إن الدعوة هتستمر،\nفربنا هو إللي بيسخر الناس لحماية الدعوة وتبليغها\nلكن بعد موت أبي طالب الأذى اشتد جدا على رسول الله ﷺ \nكل الكراهية والعداء إللي كانت جواهم طلعت دلوقتي\nماهو رسول الله ﷺ بقى في موضع ضعف،\nهم كانوا قبل كده بيؤذوه بس مش كده، وهي دي حال الكفار والمنافقين،\nطول ما الإنسان في موضع قوة ولو بسيط تلاقيه بيحترمك وحتى لو آذاك مش بيؤذيك أوي،\nلكن أول ما تروح عنك القوة يظهر بقى كل المستخبي، ويتفننوا في الإفتراءات والإتهامات بالباطل\nحتى رسول الله ﷺ قال إن قريش مخدتش راحتها في أذيته غير بعد موت أبي طالب\nتخيلوا الأذى إللي كان بيحصل له ده كله كان يعتبر حاجة بسيطة بالنسبة للي عملوه بعد كده\nلدرجة إن السفهاء تجرأوا على رسول الله ﷺ\nوفي وسط كل الشدائد والابتلاءات دي حصل ابتلاء تاني أشد\nيا ترى إيه الإبتلاء إللي حصل ، \nوإزاي رسول الله ﷺ هيقدر يكمل في طريق الدعوة وسط الصعوبات والآلام دي كلها،\nده إللي هنعرفه الجزء الجاي إن شاء الله"}]);
